INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('freelance-graphics-design', 'Freelance Graphics Design', '🎨', 'Turn Canva and Photoshop skills into a ₦200k+/month design business serving Nigerian SMEs and global clients.', '3–5 weeks to first paid client', '[{"num": 1, "title": "Build Your Toolkit", "time": "Week 1", "steps": [{"icon": "🎨", "name": "Master 1 tool deeply", "desc": "Choose Canva Pro or Adobe Illustrator. Complete one full beginner course on YouTube — don\'t spread across tools yet. Depth beats breadth.", "tools": ["Canva Pro", "Adobe Illustrator (free trial)", "YouTube: Satori Graphics"]}, {"icon": "📁", "name": "Create 10 portfolio pieces", "desc": "Design logos, social media posts, flyers, and a brand identity pack for fictional Nigerian businesses (suya spot, law firm, fashion brand). Quality > quantity.", "tools": ["Canva", "Behance (free portfolio)", "Google Drive"]}]}, {"num": 2, "title": "Position & Price", "time": "Week 1–2", "steps": [{"icon": "🎯", "name": "Pick your niche", "desc": "Specialize: logo design, social media graphics, or brand identity. Specialists earn 3x more than generalists. Choose the one you most enjoy.", "tools": ["Instagram (competitor research)", "Behance"]}, {"icon": "💰", "name": "Set your rates", "desc": "Starter pricing: logo ₦10k–₦25k, social media pack ₦15k–₦40k/month, full brand identity ₦50k–₦150k. Never go below ₦5k for any single deliverable.", "tools": ["Google Sheets (pricing sheet)", "Notion"]}]}, {"num": 3, "title": "Land First Clients", "time": "Week 2–3", "steps": [{"icon": "📲", "name": "DM 20 small businesses daily", "desc": "Find businesses with ugly logos or no brand consistency on Instagram. Send a polished before/after mockup of their brand — show don\'t tell. This conversion technique works.", "tools": ["Instagram DM", "WhatsApp Business", "Canva (mockup)"]}, {"icon": "🌐", "name": "Set up Fiverr + Upwork", "desc": "Create profiles with your best 3 portfolio samples. Write a client-focused bio: what problem you solve, not what tools you use. Apply to 10 jobs per day on Upwork.", "tools": ["Fiverr", "Upwork", "LinkedIn"]}]}, {"num": 4, "title": "Systems & Scale", "time": "Month 2+", "steps": [{"icon": "⚙️", "name": "Build reusable templates", "desc": "Create a template library for your most common deliverables. This cuts production time from 4 hours to 45 minutes — your effective hourly rate triples.", "tools": ["Canva Brand Kit", "Adobe Libraries", "Notion"]}, {"icon": "📈", "name": "Move to retainers", "desc": "Pitch your 3 best one-off clients on monthly social media design packages at ₦30k–₦80k/month. 5 retainer clients = ₦150k–₦400k stable monthly income.", "tools": ["Paystack (invoicing)", "WhatsApp", "Calendly"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('social-media-management', 'Social Media Management', '📱', 'Build a social media agency from your bedroom — manage 5 clients at ₦40k each = ₦200k/month.', '2–3 weeks to first client', '[{"num": 1, "title": "Platform Mastery", "time": "Week 1", "steps": [{"icon": "📚", "name": "Learn the algorithms", "desc": "Study Instagram, TikTok, and Facebook algorithms. Understand reach, engagement rate, and what content gets pushed organically vs paid. Take Meta Blueprint free course.", "tools": ["Meta Blueprint (free)", "TikTok Creator Academy", "YouTube: Later Blog"]}, {"icon": "🎨", "name": "Master content creation", "desc": "Practice creating 3 types: carousel posts, Reels scripts, and caption copywriting. Create a dummy brand account and post daily for 2 weeks to train your eye.", "tools": ["Canva", "CapCut", "Buffer"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 1–2", "steps": [{"icon": "📱", "name": "Manage 2 mock brand pages", "desc": "Create 2 fictional Nigerian business accounts (e.g. a restaurant and a fashion store). Manage them for 2 weeks — this is your live portfolio when pitching real clients.", "tools": ["Instagram", "TikTok", "Meta Business Suite"]}, {"icon": "📊", "name": "Document growth metrics", "desc": "Screenshot follower growth, reach, and engagement improvements on your mock accounts. Real numbers — even from fictional accounts — are powerful proof.", "tools": ["Instagram Insights", "Meta Business Suite", "Google Slides"]}]}, {"num": 3, "title": "Land First Paying Clients", "time": "Week 2–3", "steps": [{"icon": "🎯", "name": "Cold DM 30 businesses/day", "desc": "Find businesses with poor social media: low engagement, inconsistent posting, bad visuals. Send a specific 3-line critique + offer to manage their page for 30 days free.", "tools": ["Instagram DM", "WhatsApp", "LinkedIn"]}, {"icon": "🤝", "name": "Free trial → paid contract", "desc": "First 2 clients get 30 days free. Deliver outstanding results. Then present an analytics report and convert to ₦30k–₦60k/month retainer with the proof in their hands.", "tools": ["Canva", "Meta Business Suite", "Google Docs"]}]}, {"num": 4, "title": "Scale to Agency", "time": "Month 2+", "steps": [{"icon": "⚙️", "name": "Build systems and SOPs", "desc": "Create content calendars, approval workflows, and template libraries. This lets you manage 5–8 clients without burnout. Document everything in Notion.", "tools": ["Notion", "Buffer", "Google Drive", "Trello"]}, {"icon": "👥", "name": "Hire junior creators", "desc": "At ₦200k+ revenue, hire a content creator at ₦30k–₦50k/month. You become the strategist. One hire lets you take on 3 more clients with the same working hours.", "tools": ["LinkedIn (hiring)", "Slack", "Trello"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('content-writing-copywriting', 'Content Writing & Copywriting', '✍️', 'Write your way to ₦300k/month — serving Nigerian startups and international clients with no degree required.', '2–4 weeks to first paid article', '[{"num": 1, "title": "Craft & Niche", "time": "Week 1", "steps": [{"icon": "📖", "name": "Understand the 3 types", "desc": "Learn the difference: SEO content (drives Google traffic), copywriting (drives sales), and thought leadership (builds authority). Each pays differently. Copywriting pays most per word.", "tools": ["HubSpot Academy (free)", "Copyblogger", "YouTube: Alex Cattoni"]}, {"icon": "✍️", "name": "Write 5 portfolio articles", "desc": "Pick a niche you know: finance, health, tech, food, or real estate. Write 3 SEO articles (1000+ words) and 2 sales pages. Post them on Medium for a free portfolio link.", "tools": ["Google Docs", "Grammarly (free)", "Medium", "Hemingway App"]}]}, {"num": 2, "title": "Setup & First Clients", "time": "Week 1–2", "steps": [{"icon": "🌐", "name": "Create your platform profiles", "desc": "Set up Fiverr, Upwork, and a LinkedIn profile. Use a professional headshot, write a client-focused bio (their problem, your solution), and add your Medium portfolio link.", "tools": ["Fiverr", "Upwork", "LinkedIn"]}, {"icon": "📧", "name": "Send cold pitches to Nigerian startups", "desc": "Find Nigerian tech startups on LinkedIn and Twitter. Pitch them on blog content: \'I\'ll write 4 SEO articles for you monthly for ₦80k — here are 2 free samples.\' Send 10 pitches/day.", "tools": ["LinkedIn", "Gmail", "Hunter.io (free)"]}]}, {"num": 3, "title": "Win + Deliver", "time": "Week 2–4", "steps": [{"icon": "⭐", "name": "Over-deliver on first 3 clients", "desc": "Always submit before deadline. Add a bonus: a meta description, a suggested title variation, or an extra section. Clients who are delighted become repeat buyers and referrers.", "tools": ["Google Docs", "Grammarly", "SurferSEO (free trial)"]}, {"icon": "💰", "name": "Raise rates every 5 reviews", "desc": "Start at ₦5k/article, raise to ₦10k after 5 reviews, then ₦20k+ after 10. On Upwork, raise your hourly rate every 3 months. Track your monthly effective hourly rate.", "tools": ["Fiverr Analytics", "Upwork", "Notion"]}]}, {"num": 4, "title": "Scale to Agency", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Build retainer packages", "desc": "Pitch best clients on monthly content packages: 8 articles/month for ₦150k. Predictable income beats chasing new clients every month.", "tools": ["Notion", "Paystack", "Google Drive"]}, {"icon": "👥", "name": "Subcontract and scale", "desc": "When you\'re at 3+ retainers, hire 2 junior writers at ₦20k–₦40k/month. You edit and manage client relationships. Your income scales beyond your writing hours.", "tools": ["Upwork (hiring)", "Slack", "Trello"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('video-editing', 'Video Editing', '🎬', 'Edit Reels, YouTube videos, and brand ads from home — reach ₦250k/month serving creators and businesses.', '3–4 weeks to first paid edit', '[{"num": 1, "title": "Learn the Tools", "time": "Week 1–2", "steps": [{"icon": "🎬", "name": "Master CapCut or DaVinci", "desc": "Start with CapCut (free, mobile-first, clients love turnaround speed). Graduate to DaVinci Resolve for cinematic work. Complete one full YouTube course — don\'t skip colour grading.", "tools": ["CapCut (free)", "DaVinci Resolve (free)", "YouTube: Justin Odisho"]}, {"icon": "📁", "name": "Build a 5-video portfolio", "desc": "Edit 5 sample videos: a YouTube vlog, a 60-second product ad, an Instagram Reel, a TikTok, and a talking-head interview. Show range — clients want to see versatility.", "tools": ["CapCut", "DaVinci Resolve", "Pexels (free footage)"]}]}, {"num": 2, "title": "Find Your First Clients", "time": "Week 2–3", "steps": [{"icon": "📲", "name": "Target Nigerian YouTubers", "desc": "Search YouTube for Nigerian channels with 5k–100k subscribers. DM them: \'I edited a 60-sec teaser of your last video — here it is. I can do this for ₦15k/video.\' Attach the edit.", "tools": ["YouTube", "Instagram DM", "CapCut"]}, {"icon": "🛍️", "name": "List on Fiverr", "desc": "Create a \'Video Editing\' gig with your best 3 portfolio samples as the gig video. Offer 3 packages: Basic (Reels, ₦5k), Standard (YouTube, ₦15k), Premium (full brand video, ₦40k).", "tools": ["Fiverr", "Canva (gig images)"]}]}, {"num": 3, "title": "Deliver & Grow", "time": "Week 3–6", "steps": [{"icon": "⚡", "name": "Speed is your superpower", "desc": "Clients will pay premium for 24-hour turnaround. Most editors take 3–5 days. Promise and deliver 24-hour edits for Reels and short content. Charge 30% speed premium.", "tools": ["CapCut", "Google Drive", "WhatsApp"]}, {"icon": "🎨", "name": "Develop a signature style", "desc": "Create a recognizable edit style — specific transitions, colour grade, or text animations. When clients can identify your work at a glance, they refer you unprompted.", "tools": ["DaVinci Resolve", "Motion Array (templates)", "After Effects"]}]}, {"num": 4, "title": "Scale & Automate", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Retainers with content creators", "desc": "Pitch creators on monthly packages: 12 Reels/month for ₦60k, or 4 YouTube videos/month for ₦80k. Consistent work = consistent income.", "tools": ["Notion", "Paystack", "WhatsApp Business"]}, {"icon": "👥", "name": "Build an editing team", "desc": "At ₦200k+ revenue, bring on 1–2 junior editors at ₦20k–₦40k/month for basic cuts. You handle client communication, colour grading, and final review only.", "tools": ["Slack", "WeTransfer", "Trello"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('dropshipping-nigeria', 'Dropshipping (Jumia/Konga)', '🛒', 'Sell products online without holding stock — scale from ₦0 to ₦500k/month with the right niche and platform.', '2–4 weeks to first sale', '[{"num": 1, "title": "Niche Research", "time": "Week 1", "steps": [{"icon": "🔍", "name": "Find a profitable niche", "desc": "Browse Jumia bestsellers and TikTok trending products. Look for items with consistent demand, 200%+ markup potential, and low-medium competition. Baby products, phone accessories, and kitchen gadgets perform well in Nigeria.", "tools": ["Jumia Seller Centre", "TikTok (trending)", "1688.com"]}, {"icon": "📦", "name": "Source samples", "desc": "Order 3–5 sample units from your top 2 product choices via Alibaba, 1688, or Aba/Onitsha market. Test quality yourself before selling — returns kill your margins.", "tools": ["Alibaba", "1688.com", "Aba Ariaria Market"]}]}, {"num": 2, "title": "Launch Your Store", "time": "Week 1–2", "steps": [{"icon": "📱", "name": "WhatsApp Catalogue first", "desc": "Before Jumia, build a WhatsApp Business catalogue with your products. Lower fees, direct customer relationship, faster cash. Start with your existing network before scaling to platforms.", "tools": ["WhatsApp Business", "Canva (product photos)", "Instagram"]}, {"icon": "🛒", "name": "List on Jumia/Konga", "desc": "Open a Jumia Seller account (free). List your top 5 products with professional photos and competitive pricing. Use platform keywords in your product titles for better search visibility.", "tools": ["Jumia Seller Centre", "Konga Seller Hub", "Google (keyword research)"]}]}, {"num": 3, "title": "Drive Sales", "time": "Week 2–4", "steps": [{"icon": "📢", "name": "Run ₦2,000 test ads", "desc": "Run a Facebook/Instagram ad targeting Lagos, Abuja, Port Harcourt — 25–35 age, interests matching your niche. Budget ₦2k/day for 5 days. Double down on what converts.", "tools": ["Facebook Ads Manager", "Canva (ad creatives)", "WhatsApp"]}, {"icon": "⭐", "name": "Collect reviews aggressively", "desc": "After every delivery, send a WhatsApp message asking for a Jumia review. 10 positive reviews = algorithm boost that multiplies organic visibility for free.", "tools": ["WhatsApp", "Jumia Seller Centre"]}]}, {"num": 4, "title": "Scale Up", "time": "Month 2+", "steps": [{"icon": "📦", "name": "Stock winners, drop losers", "desc": "After 30 days, double down on your top 2 products by stocking inventory — faster delivery = better reviews = more sales. Drop any product with under 3% conversion.", "tools": ["Google Sheets (tracking)", "Alibaba", "GIG Logistics"]}, {"icon": "🌐", "name": "Build your own Shopify store", "desc": "At ₦200k+ monthly revenue, move to a branded Shopify store. You own the customer relationship, pay no platform fees, and build a brand asset worth selling one day.", "tools": ["Shopify", "Flutterwave (payments)", "Facebook Pixel"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('tutoring-nigeria', 'Tutoring (JAMB/WAEC/Skills)', '📚', 'Teach what you know — earn ₦100k+/month tutoring students and professionals online and offline.', '1–2 weeks to first student', '[{"num": 1, "title": "Choose Your Niche", "time": "Week 1", "steps": [{"icon": "📖", "name": "Pick 1–3 subjects you excel in", "desc": "JAMB maths and English are highest demand. WAEC sciences, economics, and accounting are close second. Professional skills (Excel, coding, public speaking) command premium rates.", "tools": ["JAMB syllabus", "WAEC syllabus", "Google Trends Nigeria"]}, {"icon": "📝", "name": "Create a simple curriculum", "desc": "Write a 4-week lesson plan for your main subject. Students and parents pay more when they see a structured plan — it signals professionalism and reduces churn.", "tools": ["Google Docs", "Canva (curriculum PDF)", "Notion"]}]}, {"num": 2, "title": "Get Your First Students", "time": "Week 1–2", "steps": [{"icon": "📲", "name": "Post in the right places", "desc": "Share your tutoring offer in estate WhatsApp groups, university department groups, and Nairaland Education section. Use a clear post: subject, rate, availability, and your qualification.", "tools": ["WhatsApp", "Nairaland", "Facebook Groups"]}, {"icon": "🎁", "name": "Offer a free first session", "desc": "A free 1-hour trial session converts curious parents into paying clients better than any advert. Come prepared with a mini test and personalized feedback — blow them away.", "tools": ["Zoom", "Google Meet", "Physical venue"]}]}, {"num": 3, "title": "Deliver & Retain", "time": "Ongoing", "steps": [{"icon": "📊", "name": "Track and report progress", "desc": "Send parents a brief weekly WhatsApp update: \'Chidi improved on quadratic equations this week. Next week we tackle simultaneous equations.\' Parents who feel informed rarely quit.", "tools": ["WhatsApp", "Google Forms (mock tests)", "Notion"]}, {"icon": "💰", "name": "Move to group sessions", "desc": "Group sessions of 3–5 students at 60% of 1-on-1 rate means 3x your hourly income. Recruit 2–3 students at similar levels, teach them together, earn more per hour.", "tools": ["Zoom", "WhatsApp Group", "Google Classroom"]}]}, {"num": 4, "title": "Build a Tutoring Business", "time": "Month 3+", "steps": [{"icon": "🌐", "name": "Go fully online", "desc": "Teach via Zoom — remove geographic limits. One Zoom session can serve 10 students anywhere in Nigeria. Record sessions and sell as video courses for passive income.", "tools": ["Zoom", "Selar (course sales)", "YouTube (free content for marketing)"]}, {"icon": "👥", "name": "Hire other tutors", "desc": "Recruit 2–3 tutors for subjects you don\'t teach. You become the admin — take 20–30% of their earnings for sourcing clients. Your tutoring centre scales without your time.", "tools": ["WhatsApp", "Google Forms", "Paystack"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('vtu-airtime-data-reselling', 'VTU Airtime & Data Reselling', '📡', 'Start same-day with ₦5,000 — build a daily cash business reselling data and airtime across Nigeria.', 'Same day — first sale within hours', '[{"num": 1, "title": "Setup in 24 Hours", "time": "Day 1", "steps": [{"icon": "📱", "name": "Register on a VTU platform", "desc": "Sign up on VTPass, Gsubz, or Husmo. Verification is instant. Fund your wallet with ₦5,000–₦20,000 via bank transfer. You are now in business — no office needed.", "tools": ["VTPass.com", "Gsubz", "Husmo VTU"]}, {"icon": "📲", "name": "Set up WhatsApp Business", "desc": "Create a WhatsApp Business profile with your brand name, business category, and a clear price list. Add an automated greeting message. This is your storefront.", "tools": ["WhatsApp Business", "Canva (price list image)"]}]}, {"num": 2, "title": "Build Your Customer Base", "time": "Week 1", "steps": [{"icon": "📢", "name": "Broadcast your rates everywhere", "desc": "Post your data rates daily in 5 WhatsApp groups. Target: student groups, market trader groups, NYSC groups, estate groups. Post at 7am and 6pm — peak purchase times.", "tools": ["WhatsApp", "Facebook Groups", "Twitter/X"]}, {"icon": "🎯", "name": "Target bulk buyers", "desc": "One cyber café buying ₦5k of data daily is worth more than 20 individual customers. Approach cyber cafes, charging shops, and phone repair shops with a bulk discount.", "tools": ["WhatsApp", "Personal visits (physical locations)"]}]}, {"num": 3, "title": "Scale Your Volume", "time": "Week 2–4", "steps": [{"icon": "💰", "name": "Reinvest profits into wallet", "desc": "Every naira of profit goes back into your VTU wallet to increase your buying capacity. A ₦5k wallet that earns ₦500/day reinvested for 30 days becomes a ₦20k wallet.", "tools": ["Google Sheets (daily P&L)", "VTPass dashboard"]}, {"icon": "🤝", "name": "Recruit sub-agents", "desc": "Train 3–5 friends on the same VTU platform. Give them a 1% better rate than your customers. They sell, you earn a spread from their sales with zero extra work from you.", "tools": ["VTPass reseller program", "WhatsApp"]}]}, {"num": 4, "title": "Expand to Full FinTech Services", "time": "Month 2+", "steps": [{"icon": "📊", "name": "Add bill payments", "desc": "VTPass and similar platforms also handle DSTV, NEPA, and cable TV payments. Every customer who buys data can also pay their bills through you. Revenue per customer triples.", "tools": ["VTPass (all services)", "WhatsApp Business"]}, {"icon": "🏧", "name": "Graduate to POS agent", "desc": "Open a full OPay or Moniepoint POS terminal alongside your VTU. Your existing customers now use you for withdrawals, transfers, and bill payments — full financial services in one spot.", "tools": ["OPay Business", "Moniepoint", "PalmPay"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('mini-importation', 'Mini Importation from China', '🌍', 'Import trending products from China and sell for 300–500% profit — scale from ₦30k to ₦800k/month.', '4–6 weeks from first order to first sale', '[{"num": 1, "title": "Product Research", "time": "Week 1", "steps": [{"icon": "🔍", "name": "Find trending products", "desc": "Scroll TikTok\'s For You page, check Jumia bestseller lists, and search 1688.com top sellers. Look for products selling in China for ₦500–₦2,000 that retail in Nigeria for ₦5,000–₦15,000.", "tools": ["TikTok (product research)", "1688.com", "Jumia (competitor pricing)"]}, {"icon": "📦", "name": "Validate demand before ordering", "desc": "Post product photos on WhatsApp Status and Instagram Stories with \'Would you buy this for ₦X?\' Collect DMs. If 5+ genuine enquiries in 24 hours — order. If silence — skip.", "tools": ["WhatsApp Status", "Instagram Stories", "Google Forms"]}]}, {"num": 2, "title": "Source & Import", "time": "Week 1–3", "steps": [{"icon": "🛒", "name": "Order from 1688 or Alibaba", "desc": "1688 is cheaper (domestic Chinese market). Alibaba has easier English interface. For first order, buy minimum quantities — 20–50 units. Test quality before scaling.", "tools": ["1688.com", "Alibaba", "Ekohub (freight)", "Cowrywise (FX)"]}, {"icon": "✈️", "name": "Choose your freight forwarder", "desc": "Use an air freight agent for fast delivery (7–14 days, ₦3,000–₦5,000/kg) for your first order. Sea freight is cheaper but 45–60 days. Pay extra for speed while learning the process.", "tools": ["Ekohub", "Topship", "DHL Express"]}]}, {"num": 3, "title": "Sell Out Fast", "time": "Week 3–5", "steps": [{"icon": "📸", "name": "Professional product photos", "desc": "Photograph your products on a clean white background or a lifestyle context. Use your phone with a ₦1,000 lightbox from Computer Village. Good photos double conversion rate.", "tools": ["iPhone/Android camera", "Canva (editing)", "Lightbox (₦1k)"]}, {"icon": "📢", "name": "Multi-channel sales attack", "desc": "List on Jumia and Konga, post daily on WhatsApp Status and Instagram, and run a ₦3k Facebook ad targeting Lagos/Abuja. Hit all channels simultaneously to move inventory fast.", "tools": ["Jumia Seller Centre", "WhatsApp Business", "Facebook Ads Manager"]}]}, {"num": 4, "title": "Build a Brand", "time": "Month 2+", "steps": [{"icon": "🏷️", "name": "Private label your products", "desc": "Order your 2 best-selling products with your own brand name printed on packaging. Branded products command 30–50% premium and build customer loyalty.", "tools": ["Alibaba (custom packaging)", "Canva (logo)", "Shopify"]}, {"icon": "🔄", "name": "Set up monthly import cycles", "desc": "Once you know which products sell, place bulk orders monthly. Negotiate 10–20% discounts for volume. Monthly restocking = consistent revenue without seasonal gaps.", "tools": ["Google Sheets", "WhatsApp (supplier contact)", "Topship"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('affiliate-marketing', 'Affiliate Marketing', '🔗', 'Earn commissions promoting Nigerian and international products — build passive income that works while you sleep.', '4–8 weeks to first commission', '[{"num": 1, "title": "Platform & Niche", "time": "Week 1", "steps": [{"icon": "🎯", "name": "Choose your niche", "desc": "Pick a niche you understand: finance, health, tech gadgets, fashion, or education. You must create content consistently about this topic — passion and knowledge show.", "tools": ["Google Trends Nigeria", "TikTok (niche research)", "Jumia KOL program"]}, {"icon": "🔗", "name": "Join affiliate programs", "desc": "Start with Jumia KOL (instant approval, Nigerian products), Konga affiliate, and Expertnaire (digital products, 30–50% commission). International: ClickBank and Amazon Associates.", "tools": ["Jumia KOL", "Expertnaire.com", "ClickBank", "Amazon Associates"]}]}, {"num": 2, "title": "Build Your Platform", "time": "Week 1–2", "steps": [{"icon": "📱", "name": "Start on TikTok or Instagram", "desc": "Short-form video is the fastest way to build an affiliate audience in Nigeria. Post product reviews, unboxings, and tutorials. 3 posts per day beats 1 polished post per week.", "tools": ["TikTok", "Instagram", "CapCut (editing)"]}, {"icon": "✍️", "name": "Create a WhatsApp broadcast list", "desc": "A WhatsApp broadcast of 200 engaged contacts converts better than 10,000 TikTok followers. Build your list from DMs, your network, and anyone who engages your content.", "tools": ["WhatsApp Business", "Linktree (bio link)"]}]}, {"num": 3, "title": "Drive Traffic & Conversions", "time": "Week 2–6", "steps": [{"icon": "📝", "name": "Review content converts best", "desc": "\'I bought and tested this product — here is my honest review\' videos perform 4x better than promotional content. Be genuinely helpful and commissions follow.", "tools": ["TikTok", "YouTube Shorts", "CapCut"]}, {"icon": "⏰", "name": "Post at peak Nigerian hours", "desc": "Post at 7–8am, 12–1pm, and 7–9pm Nigeria time. These are peak scroll times. Consistent posting schedule trains the algorithm to push your content reliably.", "tools": ["Later (scheduling)", "TikTok", "Instagram"]}]}, {"num": 4, "title": "Build for Passive Income", "time": "Month 2+", "steps": [{"icon": "🌐", "name": "Start an SEO blog", "desc": "Write product review articles optimized for Google search. A well-ranked review article earns commissions every month for years with zero maintenance. This is true passive income.", "tools": ["WordPress (free)", "Google Keyword Planner", "Rank Math SEO (free)"]}, {"icon": "📧", "name": "Build your email list", "desc": "An email list is your most valuable asset — no algorithm controls it. Offer a free guide (e.g. \'10 Best Budget Phones Under ₦50k\') to collect emails. Promote affiliate products to your list.", "tools": ["Mailchimp (free)", "ConvertKit", "Selar"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('phone-repair-accessories', 'Phone Repair & Accessories', '📱', 'Fix screens and batteries — earn ₦5k–₦15k daily in a business with constant Nigerian demand.', '3–4 weeks training + setup', '[{"num": 1, "title": "Learn the Trade", "time": "Week 1–2", "steps": [{"icon": "🎓", "name": "Learn repair basics", "desc": "Watch JerryRigEverything, Hugh Jeffreys, and Phone Repair Guru on YouTube. Focus on: screen replacement, battery replacement, charging port repair, and software flashing. These cover 80% of jobs.", "tools": ["YouTube: JerryRigEverything", "YouTube: Hugh Jeffreys", "iFixit (repair guides)"]}, {"icon": "🔧", "name": "Buy your starter tool kit", "desc": "A complete phone repair kit costs ₦8k–₦15k from Computer Village Lagos or Aba. Include: suction cup, spudger set, heat gun, precision screwdrivers, and tweezers. Quality tools prevent damage.", "tools": ["Computer Village Lagos", "Aba Ariaria Market", "iFixit Pro Tech Toolkit"]}]}, {"num": 2, "title": "Source Parts & Set Up", "time": "Week 2–3", "steps": [{"icon": "📦", "name": "Source quality spare parts", "desc": "Buy Samsung, Tecno, Infinix, and iPhone screens from Computer Village or Aba. Start with the most common models in Nigeria: Samsung A-series, Tecno Camon, Infinix Hot. Test every part before buying bulk.", "tools": ["Computer Village Lagos", "Aba (Ariaria Market)", "Alibaba (bulk orders)"]}, {"icon": "📍", "name": "Choose your setup type", "desc": "Home service: zero rent cost, build via WhatsApp referrals. Shop in market: ₦5k–₦30k/month rent, walk-in traffic. Roadside kiosk: cheapest setup, best visibility in busy areas.", "tools": ["WhatsApp Business", "Google My Business (free listing)"]}]}, {"num": 3, "title": "Build Your Customer Base", "time": "Week 3–4", "steps": [{"icon": "📲", "name": "Market in estate WhatsApp groups", "desc": "Post in your estate group: \'I fix cracked screens in 30 minutes — ₦5,000 for most phones. DM me.\' Include a before/after photo. You will get 3–5 enquiries within an hour.", "tools": ["WhatsApp", "Facebook Marketplace", "Instagram"]}, {"icon": "🛡️", "name": "Offer warranty", "desc": "A 30-day parts warranty costs you almost nothing but builds massive trust. It\'s the single most powerful trust signal for phone repair — no one else in your area likely offers it.", "tools": ["WhatsApp (warranty tracking)", "Notebook"]}]}, {"num": 4, "title": "Scale Your Income", "time": "Month 2+", "steps": [{"icon": "🛒", "name": "Sell accessories alongside repairs", "desc": "Stock phone cases, screen protectors, chargers, earphones, and power banks. Accessory margins are 100–300% and every repair customer is a warm lead for accessories.", "tools": ["Alibaba (accessories bulk)", "Computer Village", "Instagram Shop"]}, {"icon": "👥", "name": "Train an apprentice", "desc": "A trained apprentice handles basic repairs while you focus on complex jobs and business development. Pay ₦15k–₦25k/month, earn 3x that from their labour. Classic Nigerian trade model.", "tools": ["WhatsApp", "NABTEB (skills certification)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('ai-prompt-engineering', 'AI Prompt Engineering', '🤖', 'Help Nigerian businesses use AI tools to save time and make money — a new, high-paying skill with almost no competition.', '2–3 weeks to first client', '[{"num": 1, "title": "Master the Skill", "time": "Week 1", "steps": [{"icon": "🤖", "name": "Learn prompting fundamentals", "desc": "Complete Learn Prompting (free), then study advanced techniques: chain-of-thought, role prompting, few-shot examples, and structured outputs. Spend 2 hours daily for 7 days.", "tools": ["LearnPrompting.org (free)", "Claude.ai", "ChatGPT", "Midjourney"]}, {"icon": "💼", "name": "Build 5 business use cases", "desc": "Create documented case studies: AI for customer service scripts, AI for social media content, AI for email marketing, AI for data analysis, AI for product descriptions. Show real before/after output comparisons.", "tools": ["Claude.ai", "ChatGPT", "Google Docs", "Canva (case study design)"]}]}, {"num": 2, "title": "Package Your Service", "time": "Week 1–2", "steps": [{"icon": "📦", "name": "Create service packages", "desc": "Package 1 - AI Audit (₦30k): show a business how AI can save 10+ hours/week. Package 2 - AI Setup (₦80k): implement AI tools and build custom prompts. Package 3 - AI Retainer (₦50k/month): ongoing AI optimization.", "tools": ["Canva (services brochure)", "Notion", "Paystack"]}, {"icon": "🎥", "name": "Create demo content", "desc": "Record a 3-minute screen recording showing an AI writing a business proposal, social media content, or customer service response in real time. This demo sells the service itself.", "tools": ["Loom (free)", "Claude.ai", "LinkedIn"]}]}, {"num": 3, "title": "Land First Clients", "time": "Week 2–3", "steps": [{"icon": "🎯", "name": "Target SMEs on LinkedIn", "desc": "Find owners of Lagos and Abuja SMEs on LinkedIn. Comment valuably on their posts for 3 days, then DM: \'I help businesses like yours save 15 hours/week using AI. Can I show you a 10-minute demo?\'", "tools": ["LinkedIn", "Calendly (free demo booking)", "Loom"]}, {"icon": "📢", "name": "Create educational content", "desc": "Post daily LinkedIn content explaining one AI tip for Nigerian business owners. \'How to write your entire week of social media in 20 minutes using Claude.\' Educational content attracts inbound clients.", "tools": ["LinkedIn", "Twitter/X", "ChatGPT (content ideas)"]}]}, {"num": 4, "title": "Scale to Agency", "time": "Month 2+", "steps": [{"icon": "🏢", "name": "Niche down to one industry", "desc": "Real estate agents, law firms, hospitals, and logistics companies each have specific AI use cases. A specialist earns 3x a generalist. Pick the industry you understand best.", "tools": ["LinkedIn (industry targeting)", "Industry WhatsApp groups"]}, {"icon": "📚", "name": "Sell a course", "desc": "Document your system into a 4-week online course: \'AI Tools for Nigerian Business Owners.\' Sell on Selar or Udemy for ₦10k–₦30k. One course can generate ₦500k+ with the right audience.", "tools": ["Selar.co", "Zoom (recordings)", "Canva (slides)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('pos-super-agent', 'POS Super Agent (Multi-Terminal)', '🏧', 'Deploy multiple POS terminals and earn daily commission from every transaction — build a passive income infrastructure.', '2–3 weeks to first terminal deployed', '[{"num": 1, "title": "Apply & Get Licensed", "time": "Week 1", "steps": [{"icon": "📋", "name": "Apply for super-agent license", "desc": "Apply on OPay Business, Moniepoint Agency Banking, or PalmPay\'s agent portal. Submit BVN, CAC documents (or personal ID), bank account, and passport photos. Approval takes 3–7 days.", "tools": ["OPay Business App", "Moniepoint App", "PalmPay Business"]}, {"icon": "🎓", "name": "Complete agent training", "desc": "All 3 platforms offer free online training and certification. Complete the full module — it covers float management, fraud prevention, and dispute resolution. You need this to protect yourself.", "tools": ["OPay Agent Academy", "Moniepoint Training Portal"]}]}, {"num": 2, "title": "Deploy Your First Terminal", "time": "Week 1–2", "steps": [{"icon": "📍", "name": "Scout high-traffic locations", "desc": "Best locations: market entrances, bus parks, church areas on Sundays, near ATMs that are always dry, campus gates, and hospital entrances. Evaluate foot traffic at different times before committing.", "tools": ["Google Maps", "Personal scouting visits"]}, {"icon": "🤝", "name": "Partner with location owners", "desc": "Negotiate with shop owners to host your terminal: ₦5k–₦15k/month location fee or revenue sharing (give host 10–20% of your daily commission). A good location is worth fighting for.", "tools": ["WhatsApp (location agreements)", "Simple written agreement"]}]}, {"num": 3, "title": "Scale to Multiple Terminals", "time": "Month 1–2", "steps": [{"icon": "📊", "name": "Track daily per-terminal income", "desc": "Each terminal should earn ₦3k–₦8k/day net commission. Track via the platform dashboard. Any terminal below ₦2k/day after 2 weeks — relocate it immediately.", "tools": ["OPay Dashboard", "Moniepoint Dashboard", "Google Sheets (tracking)"]}, {"icon": "👥", "name": "Hire sub-agents", "desc": "Recruit trusted people to manage terminals at ₦5k–₦10k/day salary or 30% commission share. Each sub-agent you deploy is a revenue stream that pays you while you sleep.", "tools": ["WhatsApp (agent coordination)", "Cash float management"]}]}, {"num": 4, "title": "Build a Network", "time": "Month 3+", "steps": [{"icon": "🏢", "name": "Register as a corporate super-agent", "desc": "Formalize by registering your business name with CAC. Corporate super-agents access bulk terminal allocation, corporate float lines, and institutional contracts unavailable to individuals.", "tools": ["CAC (Corporate Affairs Commission)", "Sterling Bank (agent banking)"]}, {"icon": "📈", "name": "Add value-added services", "desc": "Each terminal can also process: DSTV subscriptions, NEPA bills, school fees, flight tickets, and insurance. Every additional service is a new revenue line for the same terminal and customer.", "tools": ["OPay VAS services", "Moniepoint Bills"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('ride-hailing-driver', 'Ride-Hailing Driver (Bolt/Uber)', '🚗', 'Earn ₦80k–₦250k/month driving on your schedule — maximize earnings with peak-hour strategy.', '1 week to first ride', '[{"num": 1, "title": "Onboarding", "time": "Day 1–7", "steps": [{"icon": "📱", "name": "Download and register", "desc": "Download Bolt Driver and Uber Driver apps. Have ready: valid driver\'s license, car papers (ownership + road worthiness), proof of insurance, and 4 clear car photos. Bolt approval is typically faster (3–5 days).", "tools": ["Bolt Driver App", "Uber Driver App", "CAC vehicle documents"]}, {"icon": "🚗", "name": "Prepare your car", "desc": "Clean interior and exterior thoroughly. Fix any warning lights. Stock: phone holder, charger for passengers, hand sanitizer, and small water bottles. 5-star car = 5-star tips.", "tools": ["Car wash", "Phone mount (₦1k–₦3k)", "Dashboard camera (optional)"]}]}, {"num": 2, "title": "Maximize Earnings", "time": "Week 1–2", "steps": [{"icon": "⏰", "name": "Master peak hours", "desc": "Morning peak: 6–9am (office commuters). Evening peak: 4–8pm (return traffic). Weekend nights: 8pm–2am (outings, events). Work these windows religiously — surge pricing can double your rate.", "tools": ["Bolt Driver App", "Uber Driver App", "Google Maps (traffic)"]}, {"icon": "📍", "name": "Position at demand hotspots", "desc": "Don\'t wait anywhere. In Lagos: Victoria Island, Lekki Phase 1, Ikeja GRA, and airport area. In Abuja: Maitama, Wuse II, and Garki. The app shows heatmaps — use them.", "tools": ["Bolt Heatmap", "Uber Surge Map"]}]}, {"num": 3, "title": "Build Your Rating", "time": "Month 1", "steps": [{"icon": "⭐", "name": "Chase 5 stars systematically", "desc": "Greet passengers by name (app shows it), confirm destination, offer to adjust AC, and don\'t cancel accepted rides. Rating above 4.8 unlocks premium tier on both platforms — 20% higher fares.", "tools": ["Bolt Driver App", "Uber Driver App"]}, {"icon": "💬", "name": "Build a direct client base", "desc": "After every ride, hand a business card: \'Book me directly via WhatsApp for 20% off platform price.\' A WhatsApp client base of 30+ corporate customers gives stable income outside the app.", "tools": ["WhatsApp Business", "Canva (business card design)", "VistaPrint (printing)"]}]}, {"num": 4, "title": "Scale Your Fleet", "time": "Month 3+", "steps": [{"icon": "🚗", "name": "Add a second driver", "desc": "Put a trusted driver on your car for the shifts you don\'t work. Agree on daily or weekly remittance. Your car now earns during your rest hours.", "tools": ["GPS tracker (₦15k–₦30k)", "Daily remittance agreement", "OBD diagnostic tool"]}, {"icon": "🚘", "name": "Acquire a fleet", "desc": "With 3+ cars, negotiate a hire-purchase deal on a 4th. Fleet owners managing 5–10 Bolt/Uber cars earn ₦500k–₦1.5m/month from driver remittances with minimal personal driving.", "tools": ["Car financing (Sterling Bank)", "GPS fleet tracking", "Bolt Fleet program"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('real-estate-agency', 'Real Estate Agency', '🏘️', 'Connect buyers, sellers, and renters — earn ₦50k–₦1m per deal with zero capital required.', '2–4 weeks to first listing', '[{"num": 1, "title": "Market Knowledge", "time": "Week 1–2", "steps": [{"icon": "🗺️", "name": "Study 2 neighbourhoods deeply", "desc": "Pick 2 areas: one affordable (Ikorodu, Ejigbo, Lugbe) and one premium (Lekki, Maitama). Know every street, price per sqm, landlord names, and current vacancies. Depth beats breadth.", "tools": ["Nigeria Property Centre", "PropertyPro.ng", "Physical area walks"]}, {"icon": "📋", "name": "Build your property database", "desc": "Create a spreadsheet of every available property you know: address, asking price, rooms, contact. This database is your business asset — guard it. Start with 20 listings minimum.", "tools": ["Google Sheets", "WhatsApp (landlord contacts)", "Jiji.ng"]}]}, {"num": 2, "title": "Build Your Network", "time": "Week 1–2", "steps": [{"icon": "🤝", "name": "Network with landlords", "desc": "Visit properties in your area. Tell landlords: \'I have serious buyers and renters — list with me, I charge 10% from the tenant/buyer only, you pay nothing.\' Most will list immediately.", "tools": ["WhatsApp", "Business cards", "Personal visits"]}, {"icon": "🔗", "name": "Partner with established agents", "desc": "Find 3 experienced agents in your area. Tell them: \'I\'ll bring you buyers — split commission 50/50.\' You get market access and commission without owning the listing.", "tools": ["NIESV directory", "PropertyPro agent listings", "LinkedIn"]}]}, {"num": 3, "title": "Market Properties", "time": "Week 2–4", "steps": [{"icon": "📸", "name": "Professional property photos", "desc": "Good photos on Nigeria Property Centre get 5x more enquiries. Use your phone — wide angle, bright light, no clutter. Shoot at midday for best natural light. 10 photos minimum per property.", "tools": ["iPhone/Android camera", "PropertyPro.ng", "Jiji.ng", "WhatsApp Status"]}, {"icon": "📢", "name": "Post in the right groups", "desc": "Post in: Lagos housing WhatsApp groups, Facebook real estate groups, Twitter with location hashtags. Target expat groups for premium listings. Post every 3 days — \'still available\' posts work.", "tools": ["Facebook Groups", "WhatsApp", "Twitter/X", "Instagram"]}]}, {"num": 4, "title": "Close Deals & Scale", "time": "Month 2+", "steps": [{"icon": "📜", "name": "Always use a referral letter", "desc": "Before introducing buyer to landlord, send a formal referral letter to the landlord via WhatsApp. This legally protects your 10% commission even if parties try to cut you out later.", "tools": ["Google Docs (template)", "WhatsApp", "Lawyer (for review)"]}, {"icon": "🏢", "name": "Register your real estate business", "desc": "Register with CAC and join NIESV or NIEIEN (real estate associations). Corporate agents access institutional deals — facility management contracts, developer partnerships, and land sales worth millions.", "tools": ["CAC registration", "NIESV membership", "LinkedIn"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('catering-small-chops', 'Catering & Small Chops Business', '🍱', 'Cook your way to ₦200k+/month — Nigerian events always need catering and word-of-mouth sells itself.', '1–2 weeks to first order', '[{"num": 1, "title": "Perfect Your Menu", "time": "Week 1", "steps": [{"icon": "🍳", "name": "Master 5 signature dishes", "desc": "Small chops core: spring rolls, puff puff, samosas, chicken skewers, and peppered snail. Add jollof rice for full catering. Practice until your version is better than competitors\' — blind-test with family.", "tools": ["YouTube cooking tutorials", "Local market (ingredients)", "Kitchen scale"]}, {"icon": "📦", "name": "Source packaging professionally", "desc": "Packaging sells food before taste does. Buy branded takeaway boxes, foil containers, and disposable platters from Idumota or Tejuosho market. White-label sticker with your brand name costs ₦3k–₦5k.", "tools": ["Idumota Market Lagos", "Tejuosho Market", "Canva (sticker design)"]}]}, {"num": 2, "title": "First Orders", "time": "Week 1–2", "steps": [{"icon": "📲", "name": "Post food photos everywhere", "desc": "Food photography is your marketing. Natural light, clean plate, real presentation. Post on WhatsApp Status daily, Instagram Stories, and Facebook. Video of you cooking gets more reach than still photos.", "tools": ["WhatsApp Status", "Instagram", "TikTok (cooking content)"]}, {"icon": "🎁", "name": "Start with friends and family orders", "desc": "Tell everyone you know: \'I\'m taking orders for events and daily meals — here\'s my menu.\' Friends become your first customers, reviewers, and most powerful salespeople.", "tools": ["WhatsApp", "Google Forms (order form)"]}]}, {"num": 3, "title": "Scale with Events", "time": "Month 1–2", "steps": [{"icon": "🎉", "name": "Target event planners", "desc": "Event planners are your B2B goldmine. One event planner who trusts you can send ₦500k+ of orders per month. Join their WhatsApp groups. Offer them a 10% referral commission.", "tools": ["Instagram (find planners)", "WhatsApp", "Facebook Groups"]}, {"icon": "💰", "name": "Always collect 70% deposit", "desc": "Never start cooking without a deposit. Food spoils, events get cancelled, and people default. ₦70% deposit = you cover all ingredient costs. Collect balance on delivery.", "tools": ["Paystack (payment link)", "WhatsApp", "GTBank transfer"]}]}, {"num": 4, "title": "Build a Catering Brand", "time": "Month 3+", "steps": [{"icon": "👥", "name": "Hire kitchen staff", "desc": "At 3+ events per weekend, you need help. Hire 2 cooking assistants at ₦5k–₦10k/event. You become the manager: quality control, client relations, and business development only.", "tools": ["WhatsApp (staff coordination)", "Notebook (recipe standardization)"]}, {"icon": "🏢", "name": "Target corporate accounts", "desc": "Office lunch delivery is the holy grail: recurring weekly orders, reliable payment, and no event uncertainty. Pitch to 20 offices near you: \'Daily lunch for your staff — menu rotates weekly.\' One corporate client = ₦100k+/month.", "tools": ["LinkedIn (office targeting)", "WhatsApp Business", "Paystack (subscription billing)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('fashion-design-tailoring', 'Fashion Design & Tailoring', '👗', 'Turn your sewing skills into a brand — earn ₦200k+/month from Ankara, corporate wear, and custom outfits.', '6–8 weeks from skill to first paid order', '[{"num": 1, "title": "Build Your Skill", "time": "Week 1–4", "steps": [{"icon": "🎓", "name": "Master the fundamentals", "desc": "Complete a tailoring apprenticeship (3–6 months ideally) or compress learning via YouTube: sewing machine operation, pattern drafting, cutting techniques. Start with simple straight-seam garments before complex designs.", "tools": ["YouTube: Professor Pincushion", "YouTube: Angela Wolf", "Local apprenticeship"]}, {"icon": "🪡", "name": "Buy your machine", "desc": "A Butterfly or Jack brand industrial sewing machine (₦40k–₦80k) handles heavy fabrics faster than domestic machines. Buy secondhand from Ladipo Market (Lagos) or Aba to save 40%.", "tools": ["Ladipo Market Lagos", "Aba Ariaria Market", "YouTube (machine maintenance)"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 3–6", "steps": [{"icon": "📸", "name": "Photograph your first 10 outfits", "desc": "Sew outfits for friends and family at cost price — you need portfolio photos more than money at this stage. Use a phone, a clean wall, and good lighting. Before/after body transformation shots work best.", "tools": ["Phone camera", "Canva (photo editing)", "Instagram"]}, {"icon": "🎨", "name": "Develop a signature style", "desc": "Nigerian tailors who specialize in a style get more referrals. Choose: Ankara corporate, wedding asoebi, modest fashion, or streetwear. A specialty makes you the go-to person for that niche.", "tools": ["Pinterest (design inspiration)", "Instagram (niche research)"]}]}, {"num": 3, "title": "Get Clients", "time": "Month 2", "steps": [{"icon": "📲", "name": "Instagram is your catalogue", "desc": "Post every completed outfit. Use hashtags: #LagosTailor #NigerianFashion #AnkaraStyles #CustomMade. Reply to every comment within 1 hour. Instagram DMs are your sales channel.", "tools": ["Instagram", "TikTok (speed-sewing videos)", "WhatsApp Business"]}, {"icon": "🎉", "name": "Target aso-ebi orders", "desc": "One aso-ebi group order (20–50 matching outfits) earns more than 2 months of individual clients. Network with event planners and bride families — one wedding can earn ₦300k–₦800k.", "tools": ["WhatsApp Groups", "Instagram (wedding tags)", "Facebook Groups"]}]}, {"num": 4, "title": "Build a Fashion Business", "time": "Month 3+", "steps": [{"icon": "🏷️", "name": "Launch your fashion brand", "desc": "Register a brand name, create an Instagram page separate from your personal account, and build a price list. A brand commands premium pricing that a \'tailor\' cannot charge.", "tools": ["CAC registration", "Instagram", "Canva (brand assets)"]}, {"icon": "👗", "name": "Move to Ready-to-Wear", "desc": "Sew outfits in standard sizes (S, M, L, XL) and sell online. Ready-to-wear removes the client measurement back-and-forth and lets you sell to anyone in Nigeria via Instagram and Jiji.", "tools": ["Instagram Shop", "Jiji.ng", "GIG Logistics (delivery)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('grasscutter-farming', 'Grasscutter (Cane Rat) Farming', '🐀', 'Low-risk, high-value livestock farming — each animal sells for ₦8k–₦25k with almost zero feed cost.', '6–12 months to first harvest', '[{"num": 1, "title": "Education & Setup", "time": "Week 1–2", "steps": [{"icon": "📚", "name": "Learn grasscutter husbandry", "desc": "Grasscutters are easy: they rarely get sick, eat almost anything, and reproduce fast. Watch Nigerian farming YouTube channels and visit at least one existing farm before investing a naira.", "tools": ["YouTube: Nigerian Agribusiness", "NASC (National Agricultural Seeds Council)", "Existing farm visits"]}, {"icon": "🏗️", "name": "Build your housing", "desc": "A wooden or concrete cage system: 60cm × 90cm per breeding unit (1 male + 4 females). Build with locally sourced wood and wire mesh — ₦10k–₦30k DIY for 2 breeding units. Shade and ventilation are critical.", "tools": ["Local carpenter", "Wire mesh (hardware store)", "Concrete blocks (optional)"]}]}, {"num": 2, "title": "Acquire Breeding Stock", "time": "Week 2–3", "steps": [{"icon": "🐀", "name": "Buy quality breeding pairs", "desc": "Source from reputable farms — not market sellers. One breeding unit: 1 male + 4 females. Buy weaned young adults (3–5 months old), not pregnant animals (stress causes miscarriage). Budget ₦15k–₦40k per breeding unit.", "tools": ["NASC verified farms", "Online farming communities", "WhatsApp farming groups"]}, {"icon": "🌿", "name": "Secure your feed supply", "desc": "Grasscutters eat elephant grass, sugarcane, cassava peels, sweet potato vine, and guinea grass — mostly free if you have farm access. Supplement with pellets (₦3k–₦8k/bag) for faster growth.", "tools": ["Local farms (free crop residue)", "NASC pellet feed", "Cassava farmers (free peels)"]}]}, {"num": 3, "title": "Manage for Maximum Reproduction", "time": "Month 1–6", "steps": [{"icon": "📊", "name": "Track every animal and cycle", "desc": "Each female gives birth 2× yearly, 4–8 pups per litter. Track breeding dates, pregnancy, and birth dates in a notebook. Poorly managed records = missed reproduction cycles = lost profit.", "tools": ["Notebook", "WhatsApp (farming community)"]}, {"icon": "💊", "name": "Health management", "desc": "Grasscutters are hardy but monitor for: respiratory infections (draft and damp cause most issues), wounds from cage fights, and worm infestations. Prevention cost: ₦500–₦1,000/month per unit.", "tools": ["Local vet", "Ivermectin (dewormer)", "Multivitamins"]}]}, {"num": 4, "title": "Sell at Maximum Value", "time": "Month 6+", "steps": [{"icon": "💰", "name": "Direct sale to restaurants and suya spots", "desc": "Live grasscutter sold directly to restaurant owners and suya spots earns ₦8k–₦25k per animal — 50–100% more than market price. Build a WhatsApp list of 10 restaurant contacts.", "tools": ["WhatsApp (buyer list)", "Facebook Farm groups", "OLX/Jiji listing"]}, {"icon": "📦", "name": "Value-added: smoked grasscutter", "desc": "Smoked grasscutter sells for 2–3× live price in Abuja and Lagos restaurants. Buy a smoker (₦15k–₦30k) and process your animals before selling — transforms your income per animal dramatically.", "tools": ["Charcoal smoker", "Facebook Marketplace", "Abuja/Lagos restaurant contacts"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('forex-trading', 'Forex Trading (USD/NGN)', '📈', 'Build a profitable trading system — from demo to live account — with discipline and risk management as your core edge.', '3–6 months demo before going live', '[{"num": 1, "title": "Education First", "time": "Month 1", "steps": [{"icon": "📚", "name": "Learn trading fundamentals", "desc": "Study: how forex markets work, major vs minor pairs, pips and lots, leverage mechanics, and the role of central banks. Do NOT skip this. Undereducated traders lose money predictably.", "tools": ["BabyPips School of Pipsology (free)", "YouTube: The Trading Channel", "Investopedia"]}, {"icon": "📊", "name": "Learn technical analysis", "desc": "Master: candlestick patterns, support and resistance, trend lines, moving averages (EMA 20, 50, 200), and RSI. These 5 concepts power 90% of profitable retail strategies.", "tools": ["TradingView (free)", "YouTube: Rayner Teo", "BabyPips"]}]}, {"num": 2, "title": "Demo Trading", "time": "Month 1–3", "steps": [{"icon": "🖥️", "name": "Trade demo for 90 days minimum", "desc": "Open a demo account on Exness or IC Markets. Trade as if it is real money — same lot sizes, same rules, same emotions. A profitable demo over 90 days is the minimum standard to go live.", "tools": ["Exness Demo", "IC Markets Demo", "TradingView", "Trading journal (Google Sheets)"]}, {"icon": "📔", "name": "Keep a trading journal", "desc": "Log every trade: entry, exit, reason, result, and emotional state. Review weekly. Patterns in your losses are more valuable than patterns in your wins — they reveal your blind spots.", "tools": ["Google Sheets", "TradingView screenshot", "Notion"]}]}, {"num": 3, "title": "Go Live Conservatively", "time": "Month 3–4", "steps": [{"icon": "💰", "name": "Start with minimum deposit", "desc": "Deposit only what you can afford to lose completely: $100–$500. Apply strict 1–2% risk per trade rule. At 1% risk on $200, your maximum loss per trade is $2. Discipline > account size.", "tools": ["Exness", "HFM (HF Markets)", "IC Markets"]}, {"icon": "🛡️", "name": "Risk management is your business", "desc": "Always use stop-loss on every single trade. No exceptions. A trade without a stop-loss is gambling, not trading. Your stop-loss should be based on market structure — not emotion.", "tools": ["TradingView", "MT4/MT5 (stop-loss orders)"]}]}, {"num": 4, "title": "Build Consistency", "time": "Month 4+", "steps": [{"icon": "🎯", "name": "Focus on 2 pairs only", "desc": "Become an expert on EUR/USD and USD/NGN. Deep knowledge of 2 pairs beats shallow knowledge of 20. You will see setups others miss when you know a pair\'s personality intimately.", "tools": ["TradingView", "Economic Calendar (ForexFactory)"]}, {"icon": "📈", "name": "Compound and scale", "desc": "After 6 consecutive profitable months, double your account size. Never skip the compounding phase — traders who scale too fast before consistency go broke. Patience is the most profitable strategy.", "tools": ["Google Sheets (compound calculator)", "Exness", "Trading journal"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('weight-loss-coaching', 'Online Weight Loss & Fitness Coaching', '⚖️', 'Coach Nigerian clients to their dream body via WhatsApp and Zoom — build ₦200k/month in recurring revenue.', '3–4 weeks to first paying client', '[{"num": 1, "title": "Build Authority", "time": "Week 1–2", "steps": [{"icon": "📸", "name": "Document your own or clients\' transformations", "desc": "Transformation photos are the currency of fitness marketing. If you haven\'t had personal results, offer free coaching to 3 people in exchange for documented before/after photos and testimonials.", "tools": ["Phone camera", "Google Drive (photo storage)", "Instagram"]}, {"icon": "🎓", "name": "Get certified", "desc": "An ISSA, ACE, or NCSF online certification (some free, some ₦20k–₦80k) gives you credibility and nutrition knowledge. Most Nigerian fitness coaches skip this — it\'s an immediate differentiator.", "tools": ["ISSA (free exam promo periods)", "ACE Fitness", "YouTube: Jeff Nippard (free education)"]}]}, {"num": 2, "title": "Create Your Signature Program", "time": "Week 1–2", "steps": [{"icon": "📋", "name": "Build a 12-week transformation system", "desc": "Create a repeatable system: week-by-week workout plan, meal plan template with Nigerian foods, daily check-in structure, and a clear results promise. Document everything in Notion or Google Docs.", "tools": ["Notion", "Google Docs", "Canva (program PDF)"]}, {"icon": "💰", "name": "Price for transformation", "desc": "Charge for outcomes, not hours. A 12-week body transformation program at ₦30k–₦80k converts better than \'per session\' pricing. One-time payment upfront = committed clients who actually do the work.", "tools": ["Paystack (payment link)", "WhatsApp"]}]}, {"num": 3, "title": "Get Clients", "time": "Week 2–4", "steps": [{"icon": "📱", "name": "Create daily fitness content", "desc": "Post daily: a workout tip, a Nigerian food meal plan meal, or a motivational post. TikTok and Instagram Reels of you working out or cooking healthy Nigerian meals build trust fast.", "tools": ["TikTok", "Instagram", "CapCut (video editing)"]}, {"icon": "📢", "name": "Run a free 5-day challenge", "desc": "Announce a free \'5-Day Lose 1kg\' WhatsApp challenge. Collect numbers, add to a WhatsApp group, deliver daily workouts and meals. At the end, pitch your 12-week program. This funnel converts at 20–40%.", "tools": ["WhatsApp Group", "Google Forms (sign-up)", "Canva (challenge materials)"]}]}, {"num": 4, "title": "Scale with Group Coaching", "time": "Month 2+", "steps": [{"icon": "👥", "name": "Launch group coaching cohorts", "desc": "12-week group program: ₦10k each × 20 clients = ₦200k for the same time investment as 3 individual clients. Post results from current clients to fill the next cohort.", "tools": ["WhatsApp Group", "Zoom (weekly calls)", "Selar (cohort payment)"]}, {"icon": "📦", "name": "Create passive income products", "desc": "Sell digital products: a Nigerian meal plan PDF (₦2k), a 30-day home workout guide (₦3k), or a \'Nigerian weight loss recipe book\' (₦5k). Sell once, earn forever.", "tools": ["Selar.co", "Paystack", "Canva"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('freelance-web-design', 'WordPress Website Design', '🌐', 'Build professional websites for Nigerian and global clients — earn ₦100k–₦800k per project from your laptop.', '3–4 weeks to first portfolio site', '[{"num": 1, "title": "Learn the Stack", "time": "Week 1–2", "steps": [{"icon": "💻", "name": "Master WordPress + Elementor", "desc": "Complete a full WordPress + Elementor beginner course on YouTube (Ferdy Korpershoek is excellent). Build your first local site using XAMPP or Localwp — no hosting cost while learning.", "tools": ["YouTube: Ferdy Korpershoek", "Localwp (free local server)", "WordPress.org", "Elementor (free version)"]}, {"icon": "🎨", "name": "Learn UI basics", "desc": "Study colour theory, typography hierarchy, and whitespace. A technically built but visually poor site loses clients. Take a free Google UX Design Foundations course or study Awwwards.com for inspiration.", "tools": ["Google UX Design (Coursera)", "Awwwards.com", "Canva (prototyping)"]}]}, {"num": 2, "title": "Build Portfolio", "time": "Week 2–3", "steps": [{"icon": "🏗️", "name": "Build 3 portfolio sites", "desc": "Build: (1) a Nigerian restaurant website, (2) a professional services firm, (3) an e-commerce store. These 3 types cover 80% of client requests. Host on cheap hosting for live demo links.", "tools": ["Namecheap (₦10k/year hosting)", "WordPress", "Elementor", "WooCommerce (e-commerce)"]}, {"icon": "🌐", "name": "Create your own portfolio site", "desc": "Your personal portfolio site is your most important sales tool. Show your 3 built sites with a clean, modern personal site. The site itself demonstrates your skill more than any pitch can.", "tools": ["Elementor", "Namecheap", "Professional headshot"]}]}, {"num": 3, "title": "Get Clients", "time": "Week 3–4", "steps": [{"icon": "📲", "name": "Target Nigerian SMEs on WhatsApp", "desc": "Every small business that doesn\'t have a website is a prospect. Join business WhatsApp groups and post: \'I build professional websites from ₦50k. Here are 3 I built this month.\' Attach screenshots.", "tools": ["WhatsApp", "Instagram", "LinkedIn"]}, {"icon": "🌐", "name": "Create Fiverr and Upwork profiles", "desc": "Fiverr for international quick wins (Basic: $100, Standard: $250, Premium: $600). Upwork for project-based corporate clients ($500–$5k projects). Both platforms start slow — be patient for 4–6 weeks.", "tools": ["Fiverr", "Upwork", "Payoneer (USD receiving)"]}]}, {"num": 4, "title": "Scale with Retainers", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Sell website maintenance packages", "desc": "After every website launch, pitch: \'Monthly maintenance for ₦15k: I update content, fix bugs, renew hosting, and keep your site fast and secure.\' 10 maintenance clients = ₦150k/month passive.", "tools": ["ManageWP (multi-site management)", "Paystack", "WhatsApp Business"]}, {"icon": "🤝", "name": "Partner with digital marketers", "desc": "Social media managers and digital marketers constantly need web designers. Become the go-to partner for 5 digital marketers — each referral can earn you ₦50k–₦300k. Offer 10–20% referral fee.", "tools": ["LinkedIn", "WhatsApp", "Digital marketing groups"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('data-analyst-freelance', 'Freelance Data Analysis', '📊', 'Turn Excel or Python skills into $500–$5k per project — remote work with global clients from your Nigerian laptop.', '4–6 weeks to first project', '[{"num": 1, "title": "Build Technical Skills", "time": "Week 1–3", "steps": [{"icon": "💻", "name": "Master Excel deeply", "desc": "Most clients need Excel: pivot tables, VLOOKUP/XLOOKUP, conditional formatting, charting, and simple macros. Complete ExcelJet or Chandoo\'s free tutorials. Excel proficiency alone can earn ₦100k+ per project.", "tools": ["ExcelJet.net (free)", "Chandoo.org", "Microsoft Excel"]}, {"icon": "🐍", "name": "Add Python for premium rates", "desc": "Python with pandas and matplotlib doubles your earning potential. Learn on Google Colab (free, no installation). Complete Kaggle\'s free Python and Pandas courses — both take 2 days each.", "tools": ["Google Colab (free)", "Kaggle (free courses)", "pandas", "matplotlib"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 2–4", "steps": [{"icon": "📁", "name": "Analyze 3 public datasets", "desc": "Download Nigerian economic data, public health data, or business datasets. Build 3 complete analysis projects with visualizations, insights, and recommendations. Upload to GitHub and share on LinkedIn.", "tools": ["Kaggle datasets", "Nigeria NBS datasets", "GitHub (free portfolio hosting)", "Tableau Public (free)"]}, {"icon": "📊", "name": "Create a Power BI dashboard", "desc": "A Power BI or Tableau dashboard in your portfolio commands $500–$2,000 projects. Build one with real data — Nigerian inflation data, e-commerce sales data, or healthcare data.", "tools": ["Power BI Desktop (free)", "Tableau Public (free)", "Microsoft Learn"]}]}, {"num": 3, "title": "Land First Clients", "time": "Week 3–5", "steps": [{"icon": "🌐", "name": "Start on Upwork", "desc": "Apply to \'data analyst\' projects under $200 first. Lower rates build reviews fast. After 5 reviews, raise your rate to $25–$50/hour. After 10 reviews, apply for $100+/hour projects.", "tools": ["Upwork", "LinkedIn", "GitHub (portfolio link)"]}, {"icon": "🏢", "name": "Target Nigerian SMEs directly", "desc": "Pitch to growing Nigerian businesses: \'I can turn your sales data into a dashboard that shows exactly where your profit is coming from — in 3 days.\' This pitch is specific and irresistible.", "tools": ["LinkedIn", "WhatsApp", "Email outreach"]}]}, {"num": 4, "title": "Scale Income", "time": "Month 2+", "steps": [{"icon": "💰", "name": "Specialize in one industry", "desc": "Healthcare analytics, fintech data, or agricultural market data — specialists charge 3× generalists. Pick the Nigerian industry where your domain knowledge gives you an edge.", "tools": ["LinkedIn (industry content)", "Google Scholar (industry papers)"]}, {"icon": "🔄", "name": "Build retainer relationships", "desc": "Monthly analytics retainers: ₦80k–₦200k/month for ongoing dashboard updates, monthly reports, and ad-hoc analysis. One retainer covers your basic expenses — build 3 and you\'re financially free.", "tools": ["Notion", "Paystack", "Google Data Studio (free)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('mobile-barbing', 'Mobile Barbing (Home Service)', '✂️', 'Bring the barbershop to the client — charge premium for convenience and build a loyal recurring client base.', '1–2 weeks to first bookings', '[{"num": 1, "title": "Gear Up", "time": "Week 1", "steps": [{"icon": "✂️", "name": "Invest in quality clippers", "desc": "Andis Master, Wahl Legend, or BaByliss FXs are the professional standard. Budget ₦15k–₦40k for a good set. Cheap clippers pull hair, cause bad cuts, and destroy your reputation. This investment pays for itself in 3 clients.", "tools": ["Andis Master Clipper", "Wahl Legend", "Computer Village (Lagos) for supplies"]}, {"icon": "🎒", "name": "Build your mobile kit", "desc": "Everything fits in a backpack: clippers, cape, spray bottle, comb set, scissors, handheld mirror, brush, and portable LED ring light for indoor cuts. Total kit: ₦20k–₦40k. Clean and organized kit signals professionalism.", "tools": ["Backpack", "Portable LED light", "WhatsApp Business"]}]}, {"num": 2, "title": "Perfect Your Craft", "time": "Week 1–2", "steps": [{"icon": "📸", "name": "Build a before/after portfolio", "desc": "Cut friends\' and family\'s hair and photograph every result — face-on and side profile. 20 quality before/after photos on Instagram establish your skill before you charge premium rates.", "tools": ["Phone camera", "Instagram", "Canva (portfolio layout)"]}, {"icon": "🎯", "name": "Learn premium styles", "desc": "Fade, taper, line-up, and beard styling are what busy professionals pay ₦3k–₦8k for. YouTube tutorial channels: Chuka The Barber, 360Jeezy. Invest 2 weeks mastering these before marketing.", "tools": ["YouTube: Chuka The Barber", "YouTube: 360Jeezy", "Practice mannequin head (₦5k)"]}]}, {"num": 3, "title": "Build Your Client Base", "time": "Week 2–4", "steps": [{"icon": "📲", "name": "Target your estate and neighbourhood", "desc": "Post in your estate WhatsApp group: \'Professional mobile barber — I come to your home. ₦3,000 per cut, ₦1,000 for children. DM to book.\' Add your before/after photos. 5–10 enquiries guaranteed.", "tools": ["WhatsApp", "Estate groups", "Facebook Marketplace"]}, {"icon": "🏢", "name": "Target corporate professionals", "desc": "Corporate workers hate leaving the office or home for haircuts. Offer office service (Wednesday and Thursday afternoons) or Saturday home service. Price: ₦3,500–₦6,000/cut. Once they experience convenience, they don\'t go back to barbershops.", "tools": ["LinkedIn (target companies)", "WhatsApp", "Business cards"]}]}, {"num": 4, "title": "Scale Your Business", "time": "Month 2+", "steps": [{"icon": "📅", "name": "Build a subscription model", "desc": "Pitch regular clients: \'Weekly cut for ₦8k/month, saves you ₦4k vs pay-per-cut.\' Monthly subscribers book your entire calendar, guarantee your income, and refer their colleagues automatically.", "tools": ["Paystack (monthly subscription)", "WhatsApp", "Google Calendar"]}, {"icon": "👥", "name": "Train and partner with barbers", "desc": "Recruit 2 trained barbers, supply them with kits, and take 30–40% of their bookings. You manage marketing and booking — they deliver the service. Your income grows without your hands.", "tools": ["WhatsApp (team coordination)", "Booking apps", "Cash handling system"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('nails-studio', 'Nail Technician (Home Studio)', '💅', 'Build a loyal recurring client base from your home studio — clients return every 2–3 weeks like clockwork.', '2–3 weeks to first paying client', '[{"num": 1, "title": "Invest in Training & Supplies", "time": "Week 1–2", "steps": [{"icon": "🎓", "name": "Get trained properly", "desc": "Attend a 1–3 day nail technician training (₦10k–₦30k in Lagos, Abuja, Port Harcourt). YouTube supplements but doesn\'t replace hands-on training. Proper technique prevents damage to clients\' nails — reputation-critical.", "tools": ["Instagram (find nail trainers in your city)", "YouTube: Suzie (Nail Career Education)"]}, {"icon": "💅", "name": "Buy a complete starter kit", "desc": "Gel polishes (10–20 colours), UV/LED lamp, nail drill, soft gel tips or forms, nail glue, primer, base coat, top coat, cuticle oil, and under-eye pads. Budget ₦15k–₦35k for a proper starter kit.", "tools": ["AliExpress (nail supplies)", "Nail supply stores (Computer Village Lagos)", "Amazon"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 1–2", "steps": [{"icon": "📸", "name": "Practice and photograph everything", "desc": "Practice on friends, family, and a nail training hand. Photograph every set — top-down and side angle, on black velvet background for professional look. Post daily on Instagram and TikTok.", "tools": ["Phone camera", "Black velvet cloth (₦500)", "Instagram", "TikTok"]}, {"icon": "🎨", "name": "Develop signature nail art", "desc": "Create 3–5 signature styles that show off your skill: ombre, French tips, 3D nail art, or abstract designs. Unique styles generate shares, saves, and bookings you didn\'t solicit.", "tools": ["Instagram (nail art inspiration)", "Pinterest", "Nail art brushes"]}]}, {"num": 3, "title": "Fill Your Book", "time": "Week 2–4", "steps": [{"icon": "📲", "name": "Instagram is your booking engine", "desc": "Post before/after photos daily. Use hashtags: #LagosMalatechnician #NailsAbuja #NigerianNails #NailArtNigeria. Reply to every comment. Your Instagram IS your business — treat it like your shopfront.", "tools": ["Instagram", "TikTok (speed nail tutorials)", "WhatsApp Business"]}, {"icon": "🎁", "name": "Launch a referral program", "desc": "Give every client 3 referral cards: \'Refer a friend, get ₦500 off your next visit.\' Word-of-mouth from satisfied clients fills a nail tech\'s calendar faster than any paid ad.", "tools": ["Canva (referral card design)", "VistaPrint (printing)", "WhatsApp"]}]}, {"num": 4, "title": "Scale Your Studio", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Implement a loyalty program", "desc": "After 5 visits, the 6th manicure is free. After 10, a free nail art upgrade. Loyalty programs increase average client visit frequency by 30% and eliminate ghosting between appointments.", "tools": ["WhatsApp (tracking)", "Google Sheets", "Loyalty card (Canva)"]}, {"icon": "🏫", "name": "Start teaching nail courses", "desc": "A weekend nail tech course (₦25k–₦50k per student) earns more per hour than doing nails. Teach 5 students/weekend = ₦125k–₦250k in 2 days. Your biggest students become your referral network.", "tools": ["Instagram (course promotion)", "WhatsApp", "Paystack"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('security-installation', 'CCTV & Security Camera Installation', '🔒', 'Install CCTV and security systems for homes and businesses — high-value recurring contracts, constant Nigerian demand.', '2–3 weeks to first job', '[{"num": 1, "title": "Learn the Trade", "time": "Week 1–2", "steps": [{"icon": "🎓", "name": "Complete a technical training", "desc": "Watch \'Hikvision installation Nigeria\' and \'CCTV installation complete guide\' on YouTube. Then take a 3–5 day hands-on training at a security equipment distributor in your city — most offer this free if you buy from them.", "tools": ["YouTube: Hikvision Nigeria", "CCTV installers forum", "Computer Village Lagos (training)"]}, {"icon": "🔧", "name": "Assemble your tool kit", "desc": "Buy: cable crimping tool, cable tester, electric drill, 20m fish tape, cable ties, RJ45 connectors, 6mm drill bits, and a ladder. Total: ₦15k–₦30k. Your tools are your business licence.", "tools": ["Alaba International Market", "Computer Village Lagos", "Jumia (tools)"]}]}, {"num": 2, "title": "Know Your Products", "time": "Week 1–2", "steps": [{"icon": "📹", "name": "Specialize in Hikvision and Dahua", "desc": "These 2 brands dominate Nigerian commercial installations. Learn their camera models, NVR configurations, and mobile app setup (iVMS-4200, Hik-Connect, DMSS). Most Nigerian CCTV jobs use one of these 2 brands.", "tools": ["Hikvision Nigeria (dealer training)", "iVMS-4200 (Hikvision app)", "DMSS App (Dahua)"]}, {"icon": "🏷️", "name": "Build a price list", "desc": "4-camera home system (installed): ₦50k–₦80k. 8-camera office: ₦100k–₦200k. 16-camera commercial complex: ₦250k–₦600k. Price based on camera type, cable run length, and network integration complexity.", "tools": ["Google Sheets (quotation template)", "WhatsApp Business"]}]}, {"num": 3, "title": "Get Your First Jobs", "time": "Week 2–3", "steps": [{"icon": "🏘️", "name": "Approach estate developers", "desc": "Construction sites always need CCTV before handover. Visit new estate developments and offer the developer a direct quote. One 20-unit estate = ₦1m–₦4m in CCTV work.", "tools": ["Physical estate visits", "WhatsApp", "Business cards"]}, {"icon": "🏢", "name": "Target property managers and schools", "desc": "Property managers and school owners are your best repeat clients — they manage multiple sites and frequently upgrade. One school owner can refer you to 5 other schools without asking.", "tools": ["LinkedIn", "WhatsApp", "Facebook Business Groups"]}]}, {"num": 4, "title": "Build Recurring Revenue", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Offer maintenance contracts", "desc": "After installation, pitch an annual maintenance contract: ₦10k–₦30k/year per site. This includes quarterly camera cleaning, firmware updates, and emergency callouts. 20 contracts = ₦200k–₦600k passive annual income.", "tools": ["WhatsApp", "Simple service agreement (Google Docs)", "Paystack"]}, {"icon": "🌐", "name": "Add smart home and access control", "desc": "Clients who trust your CCTV work will buy electric fences, intercoms, biometric access control, and smart doorbells from you. Each upsell is worth ₦50k–₦500k.", "tools": ["ZKTeco (access control)", "Hikvision intercom", "Amazon (smart home devices)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('podcast-production', 'Podcast Production Service', '🎙️', 'Produce, edit, and launch podcasts for business owners who want to be heard but lack the technical skills.', '2–3 weeks to first paying client', '[{"num": 1, "title": "Master Audio Production", "time": "Week 1–2", "steps": [{"icon": "🎧", "name": "Learn Audacity or Adobe Audition", "desc": "Audacity is free and powerful for beginners. Adobe Audition for advanced work. Master: noise reduction, EQ, compression, loudness normalization (LUFS-16 for Spotify), and mixing music beds.", "tools": ["Audacity (free)", "Adobe Audition (paid)", "YouTube: Booth Junkie"]}, {"icon": "🎙️", "name": "Record and edit a sample episode", "desc": "Record yourself interviewing a friend on any topic. Edit it to broadcast quality: remove filler words, tighten pauses, add intro music, and normalize volume. This is your proof of skill.", "tools": ["Audacity", "Rode NT-USB (mic) or phone", "Epidemic Sound (royalty-free music)"]}]}, {"num": 2, "title": "Package Your Services", "time": "Week 1–2", "steps": [{"icon": "📦", "name": "Define your service tiers", "desc": "Basic: audio editing only (₦15k/episode). Standard: edit + show notes + thumbnail (₦25k/episode). Premium: full production (₦50k/episode + ₦15k/month Spotify/Apple submission). Monthly retainer = stable income.", "tools": ["Canva (services brochure)", "Paystack", "Notion"]}, {"icon": "🎯", "name": "Target your ideal clients", "desc": "Best clients: business coaches, lawyers, pastors, health professionals, and corporate executives who speak publicly and want to repurpose their expertise. They have budgets and long-term commitment.", "tools": ["LinkedIn", "Instagram", "Church/business event networks"]}]}, {"num": 3, "title": "Land First Clients", "time": "Week 2–3", "steps": [{"icon": "📲", "name": "Cold DM on LinkedIn and Instagram", "desc": "Find professionals who already post valuable content. DM: \'Your insights deserve a podcast. I produce end-to-end — you record, I handle everything else. Here\'s a free 3-minute sample of your last post as audio.\'", "tools": ["LinkedIn", "Instagram", "Audacity (create free sample)"]}, {"icon": "🎤", "name": "Offer a free pilot episode", "desc": "Offer 1 free pilot episode to your 3 best prospects. Get feedback. If they love it, close at full retainer rate. If they don\'t proceed, you still have a portfolio episode to show other clients.", "tools": ["Audacity", "Google Drive", "Zoom (remote recording)"]}]}, {"num": 4, "title": "Build a Production Company", "time": "Month 2+", "steps": [{"icon": "🏢", "name": "Build a podcast studio", "desc": "A soundproofed corner in your room: acoustic panels on walls (₦5k–₦20k DIY with egg crates), a good mic, and an audio interface. Charge ₦10k–₦30k extra for studio sessions vs remote recording.", "tools": ["Focusrite Scarlett Solo (audio interface)", "Rode Procaster mic", "Acoustic foam panels"]}, {"icon": "👥", "name": "Hire an audio engineer", "desc": "At 5+ clients, hire a junior audio editor at ₦30k–₦50k/month. You handle client acquisition and strategy — they execute the editing. Your income scales without your production hours.", "tools": ["Upwork (audio editors)", "LinkedIn", "Slack"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('homemade-food-delivery', 'Homemade Cooked Food Delivery', '🍲', 'Cook the food Lagos and Abuja workers are craving — build a ₦100k+/month meal delivery business from your kitchen.', '1 week to first order', '[{"num": 1, "title": "Build Your Menu", "time": "Week 1", "steps": [{"icon": "👨‍🍳", "name": "Perfect 5 signature dishes", "desc": "Choose dishes you can make consistently and excellently: jollof rice, egusi soup, afang, pepper soup, or ayamase. Consistency matters more than variety — customers return for what they loved, not something new.", "tools": ["Recipe notebook", "WhatsApp Status (testing interest)"]}, {"icon": "📦", "name": "Source professional packaging", "desc": "Disposable takeaway containers, foil packs, and heat-seal bags (Idumota or Tejuosho market). Professional packaging makes food look valuable before it\'s tasted. Include your brand name on a sticker.", "tools": ["Idumota Market", "Canva (sticker design)", "Printivo (sticker printing)"]}]}, {"num": 2, "title": "Launch and Get Orders", "time": "Week 1–2", "steps": [{"icon": "📸", "name": "Food photography daily", "desc": "Photograph every dish before delivery: overhead shot, natural light, clean presentation. Post on WhatsApp Status by 8am and 12pm. Your daily food photo is your free daily advert to 500+ contacts.", "tools": ["WhatsApp Status", "Instagram Stories", "CapCut (video)"]}, {"icon": "🎁", "name": "Target bachelor apartments and office workers", "desc": "Post in bachelor and young professional WhatsApp groups: \'Hot homemade meals delivered by 1pm. Menu today: jollof + chicken + salad — ₦2,500.\' The longing for home-cooked food is a powerful motivator.", "tools": ["WhatsApp Groups", "Estate groups", "LinkedIn (office workers)"]}]}, {"num": 3, "title": "Build Recurring Revenue", "time": "Week 2–4", "steps": [{"icon": "🔄", "name": "Launch a weekly subscription", "desc": "Pitch regular customers on meal subscriptions: ₦12k/week for 5 weekday lunches delivered (₦2,400/meal delivered). Subscriptions give you predictable daily demand and zero marketing cost for those customers.", "tools": ["Paystack (subscription billing)", "WhatsApp", "Google Forms (preferences)"]}, {"icon": "🏍️", "name": "Partner with a dispatch rider", "desc": "Partner with a regular dispatch rider (₦500–₦1,500 per delivery). This frees you to cook more while deliveries happen — you can serve 2× more customers with the same cooking hours.", "tools": ["Glovo", "Chowdeck (restaurant partner)", "Local dispatch rider (WhatsApp)"]}]}, {"num": 4, "title": "Scale Your Kitchen", "time": "Month 2+", "steps": [{"icon": "🍽️", "name": "Add dinner and breakfast options", "desc": "Dinner meal prep (ready-to-heat, delivered by 6pm) and breakfast packs (akara, moi moi, custard) triple your daily revenue from the same kitchen without tripling cooking time.", "tools": ["WhatsApp", "Google Forms (new menu orders)"]}, {"icon": "🏢", "name": "Land corporate accounts", "desc": "One corporate account feeding 20 staff daily at ₦1,500/meal = ₦30k/day = ₦600k+/month. Pitch directly to HR managers: \'Staff lunch program — we handle delivery, variety, and dietary preferences.\'", "tools": ["LinkedIn (HR managers)", "WhatsApp", "Paystack"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('agro-export', 'Nigerian Agro-Commodity Export', '🌍', 'Export sesame, cashew, ginger, and hibiscus to China, India, and Europe — Nigeria\'s commodities are in global demand.', '3–6 months from registration to first export', '[{"num": 1, "title": "Registration & Education", "time": "Week 1–3", "steps": [{"icon": "📋", "name": "Register with NEPC", "desc": "Nigerian Export Promotion Council membership is free for individuals. NEPC gives you access to buyer databases, export documentation training, and trade missions. This is step one — no shortcuts.", "tools": ["NEPC.gov.ng", "CAC (business registration)", "Bank domiciliary account"]}, {"icon": "📚", "name": "Learn your chosen commodity", "desc": "Study one commodity deeply before diversifying: sesame (most liquid, year-round buyers), cashew (April–June peak, highest value), or ginger (stable demand from India and China). Join commodity-specific WhatsApp groups of exporters.", "tools": ["NEPC commodity reports", "TradeMap.org (free trade statistics)", "WhatsApp exporter communities"]}]}, {"num": 2, "title": "Source Your Commodity", "time": "Week 3–6", "steps": [{"icon": "🌾", "name": "Build farmer/aggregator relationships", "desc": "For sesame: Jigawa, Nassarawa, Benue. Cashew: Enugu, Kogi, Oyo. Ginger: Kaduna, Plateau, Nasarawa. Visit producing states and build relationships with 2–3 aggregators who can supply consistently.", "tools": ["WhatsApp", "Physical farm visits", "NASC (farmer directories)"]}, {"icon": "🔬", "name": "Understand quality grades", "desc": "Export buyers pay premium for Grade A: clean, dry, uniform product. Understand moisture content standards (<10% for sesame), foreign matter limits, and colour grades. Failed quality tests = rejected containers = ₦millions lost.", "tools": ["Moisture meter (₦3k–₦8k)", "NAFDAC quality standards", "NASC grading guide"]}]}, {"num": 3, "title": "Find Buyers", "time": "Month 2–3", "steps": [{"icon": "🌐", "name": "List on trade platforms", "desc": "Create detailed seller profiles on TradeKey.com, Alibaba (verified supplier), and Europages. Upload product specifications, quality certificates, and photos. Serious buyers search these platforms daily.", "tools": ["TradeKey.com (free listing)", "Alibaba Supplier", "Europages"]}, {"icon": "🤝", "name": "Use NEPC buyer-matching service", "desc": "NEPC runs trade missions and reverse trade missions where foreign buyers visit Nigeria. Attend every NEPC event — one meeting with a Chinese or European buyer at a government-organized event can generate ₦50m+ in contracts.", "tools": ["NEPC.gov.ng (events)", "Business card", "Product samples"]}]}, {"num": 4, "title": "Execute First Export", "time": "Month 3–6", "steps": [{"icon": "📄", "name": "Master export documentation", "desc": "Required: Form NXP (CBN), phytosanitary certificate (NAFDAC), certificate of origin (NCS), commercial invoice, packing list, and bill of lading. Any missing document = delayed or detained container.", "tools": ["CBN Form NXP portal", "NAFDAC office", "Nigeria Customs (NCS)"]}, {"icon": "💰", "name": "Use Letters of Credit", "desc": "Never ship on verbal agreement. Demand a Letter of Credit (LC) from your buyer — it\'s a bank guarantee of payment upon verified shipping documents. This is standard export practice that protects your cargo value.", "tools": ["Your Nigerian bank (LC department)", "Export lawyer", "NEPC trade advisory"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('online-course-creation', 'Online Course Creation', '🎓', 'Package your expertise into a course that earns while you sleep — one good course can generate ₦500k+ per year.', '4–6 weeks from idea to first sale', '[{"num": 1, "title": "Validate Your Idea", "time": "Week 1", "steps": [{"icon": "💡", "name": "Find your profitable topic", "desc": "Your course topic must sit at the intersection of: what you know well, what people are actively searching for, and what people will pay for. Finance, digital skills, exam prep, cooking, and fitness courses perform best in Nigeria.", "tools": ["Google Trends Nigeria", "Selar top sellers", "Udemy (search volume)", "Twitter/X (what people ask about)"]}, {"icon": "📊", "name": "Validate with a survey", "desc": "Post a poll or survey to your audience: \'I am building a course on X. Would you pay ₦Y for it?\' 20 genuine YES responses = validated demand. Don\'t build until you\'ve validated.", "tools": ["Google Forms", "WhatsApp poll", "Twitter poll"]}]}, {"num": 2, "title": "Create the Course", "time": "Week 2–4", "steps": [{"icon": "📝", "name": "Build a structured curriculum", "desc": "Outline 5–8 modules, each with 3–5 video lessons. Structure: Problem → Concept → Demonstration → Practice → Result. Students don\'t pay for information — they pay for transformation. Make sure every module moves them forward.", "tools": ["Notion (curriculum planning)", "Google Docs", "Canva (curriculum PDF)"]}, {"icon": "🎥", "name": "Record with what you have", "desc": "Phone camera + natural window light + a wall = professional enough. Audio is more important than video — buy a ₦5k lapel microphone. CapCut or DaVinci Resolve for simple editing. Perfect is the enemy of shipped.", "tools": ["Phone camera", "Lapel mic (₦3k–₦8k)", "CapCut (editing)", "DaVinci Resolve (advanced)"]}]}, {"num": 3, "title": "Launch and Sell", "time": "Week 4–5", "steps": [{"icon": "🛍️", "name": "List on Selar first", "desc": "Selar.co is the best Nigerian platform for digital product sales: Paystack + Flutterwave integration, automatic delivery, affiliate program, and zero setup cost. Upload your course, set your price, and start selling within an hour.", "tools": ["Selar.co", "Paystack", "WhatsApp (launch announcement)"]}, {"icon": "📢", "name": "Pre-launch to your audience", "desc": "Announce 1 week before launch: \'Pre-order at 30% discount — only 20 spots.\' Scarcity + discount + early access is a proven Nigerian digital product launch formula. Use WhatsApp, Instagram, and email.", "tools": ["WhatsApp Status", "Instagram Stories", "Mailchimp"]}]}, {"num": 4, "title": "Scale and Automate", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Build an evergreen sales funnel", "desc": "Create a free lead magnet (PDF, mini-course, or checklist) → email list → automated 5-email sequence → course pitch. This funnel sells your course every day without you doing anything.", "tools": ["Mailchimp (free)", "Selar", "Canva (lead magnet)"]}, {"icon": "💰", "name": "Create a course suite", "desc": "Your first course buyers are your best second-course buyers. Build a beginner, intermediate, and advanced tier. A suite of 3 courses with an average ₦10k price point and 100 buyers = ₦1m/month.", "tools": ["Selar", "Notion", "Paystack"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('instagram-shoutout-broker', 'Instagram Shoutout Brokerage', '📣', 'Connect brands with Nigerian influencers and earn 20–30% commission from both sides — no followers needed.', '1–2 weeks to first deal', '[{"num": 1, "title": "Build Your Influencer Database", "time": "Week 1", "steps": [{"icon": "📋", "name": "Create a pricing catalogue", "desc": "Research 100+ Nigerian Instagram pages (5k–500k followers) across niches: fashion, food, comedy, lifestyle, tech. Note their follower count, engagement rate, and estimated rate. Build this into a Google Sheet — this is your inventory.", "tools": ["Google Sheets", "Instagram", "SocialBlade (engagement check)"]}, {"icon": "🤝", "name": "DM influencers for rate cards", "desc": "Message 50 influencers: \'Hi, I\'m a brand partnership manager. Do you have a rate card for sponsored posts?\' Most will reply within 24 hours. Store every rate card — this is your price list.", "tools": ["Instagram DM", "Gmail (follow-up)", "Google Sheets"]}]}, {"num": 2, "title": "Build Your Brand Clients", "time": "Week 1–2", "steps": [{"icon": "🏢", "name": "Cold pitch Nigerian SMEs", "desc": "DM businesses on Instagram that have budget but no influencer strategy: beauty brands, fashion stores, restaurants, and lifestyle products. Pitch: \'I can get your brand on 10 Lagos fashion pages for ₦80k total this weekend.\'", "tools": ["Instagram DM", "LinkedIn", "WhatsApp"]}, {"icon": "💼", "name": "Charge both sides (transparently)", "desc": "The model: charge brand full influencer rate + your 25% markup. Pay influencer 100% of their quoted rate. Both sides win, you earn the spread. Transparency about your role builds long-term trust.", "tools": ["Google Sheets (deal tracking)", "Paystack", "WhatsApp"]}]}, {"num": 3, "title": "Execute Deals Professionally", "time": "Ongoing", "steps": [{"icon": "📄", "name": "Use simple written agreements", "desc": "Send a WhatsApp message confirming: brand name, deliverable (1 post + 2 stories), date/time, payment amount, and usage rights. Screenshot this as your contract. Verbal deals get disputed — written ones don\'t.", "tools": ["WhatsApp (written confirmations)", "Google Docs (formal contracts for big deals)"]}, {"icon": "⏰", "name": "Be the most reliable broker in Nigeria", "desc": "Nigerian influencer marketing has a reputation for flakiness. Be the broker who delivers on time, every time. Brands will pay premium for reliability — a reputation for execution is your most valuable asset.", "tools": ["Google Calendar", "WhatsApp reminders", "Notion (deal pipeline)"]}]}, {"num": 4, "title": "Scale to an Agency", "time": "Month 2+", "steps": [{"icon": "📊", "name": "Create an influencer marketing deck", "desc": "Build a professional deck showing: your influencer network, campaign examples with results (reach, engagement, sales), and your process. This is your pitch to corporate and agency clients who have ₦500k+ budgets.", "tools": ["Canva", "Google Slides", "LinkedIn"]}, {"icon": "🏢", "name": "Register as an influencer marketing agency", "desc": "Register your business, build a website, and pitch to PR agencies and marketing departments. Corporate influencer campaigns (₦500k–₦5m) replace dozens of small deals and scale income without scaling effort.", "tools": ["CAC registration", "WordPress (agency website)", "LinkedIn"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('local-seo-service', 'Google My Business / Local SEO Service', '🔍', 'Help local businesses show up on Google Maps and get more customers — charge ₦15k–₦50k per setup.', '1–2 weeks to first client', '[{"num": 1, "title": "Learn Google Business Profile", "time": "Week 1", "steps": [{"icon": "📚", "name": "Complete Google\'s free training", "desc": "Take the Google Business Profile free certification on Skillshop (2–3 hours). Understand: profile optimization, posting, review management, photo strategy, and category selection. This knowledge gap is massive in Nigeria.", "tools": ["Google Skillshop (free)", "YouTube: Darren Shaw (local SEO)"]}, {"icon": "🔍", "name": "Audit 10 local businesses", "desc": "Find 10 businesses in your area on Google Maps. Screenshot their incomplete or missing profiles. These screenshots become your pitch deck — you are showing them their own problem before you even propose a solution.", "tools": ["Google Maps", "Google Business Profile", "Screenshots (your pitch material)"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 1–2", "steps": [{"icon": "🏆", "name": "Optimize 3 profiles for free", "desc": "Offer to optimize a friend\'s business, a church, and a local restaurant for free. Take before/after screenshots: rank position, photo count, review count, and monthly views. These are your case study.", "tools": ["Google Business Profile", "Google Maps ranking tracker", "BrightLocal (free trial)"]}, {"icon": "📸", "name": "Add professional photos", "desc": "Google ranks profiles with more high-quality photos higher. Take professional photos for your free case studies: exterior, interior, product/service photos, and team photos. Include this as a premium add-on service.", "tools": ["Phone camera", "Google Business Profile photo upload"]}]}, {"num": 3, "title": "Get Paying Clients", "time": "Week 2–3", "steps": [{"icon": "🚶", "name": "Walk your street and surroundings", "desc": "Every business without a Google listing or with an incomplete one is a prospect. Restaurants, clinics, beauty salons, mechanics, and shops — approach in person with your printed before/after examples.", "tools": ["Printed case study", "Business cards", "Google Maps"]}, {"icon": "📢", "name": "Pitch in business WhatsApp groups", "desc": "Post in business owners\' groups: \'Does your business show up when people search Google? I help 10 businesses get found on Google Maps this month — DM me.\' Attach a screenshot of a business ranking first.", "tools": ["WhatsApp Groups", "Facebook Groups", "LinkedIn"]}]}, {"num": 4, "title": "Build Recurring Income", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Monthly management retainers", "desc": "After setup, pitch monthly management: posting weekly updates, responding to reviews, updating photos, and monthly performance reporting — ₦10k–₦20k/month per client. 10 clients = ₦100k–₦200k passive monthly income.", "tools": ["Google Business Profile", "Canva (monthly posts)", "Paystack"]}, {"icon": "📦", "name": "Bundle into a full digital package", "desc": "Combine Google Business Profile + WhatsApp Business setup + basic Facebook page setup into a ₦50k one-time \'Digital Presence Package.\' This triple-value offer has a very high conversion rate with Nigerian SMEs.", "tools": ["Canva (package brochure)", "Paystack", "WhatsApp Business"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('generator-repair', 'Generator Repair & Servicing', '⚡', 'Fix Nigeria\'s most constant appliance — earn ₦8k–₦30k per call-out in a market that never slows down.', '2–4 weeks training + setup', '[{"num": 1, "title": "Learn the Trade", "time": "Week 1–3", "steps": [{"icon": "🔧", "name": "Complete an apprenticeship", "desc": "Find a generator mechanic in your area and apprentice for 2–4 weeks (pay ₦5k–₦10k appreciation). Learn: carburettor cleaning/replacement, AVR (Automatic Voltage Regulator) replacement, oil servicing, spark plug replacement, and starter motor repair.", "tools": ["Local mechanic apprenticeship", "YouTube: Generator Repair Guide", "iFixit (electrical guides)"]}, {"icon": "🔩", "name": "Build your tool kit", "desc": "Essential tools: multimeter (₦3k–₦8k), carburettor cleaner spray, spark plug socket set, AVR tester, flat and Phillips screwdrivers, wire connectors, and an oil drain pan. Total: ₦15k–₦25k starter kit.", "tools": ["Alaba Market Lagos", "Computer Village", "Jumia"]}]}, {"num": 2, "title": "Know Your Products", "time": "Week 2", "steps": [{"icon": "📚", "name": "Study common generator brands", "desc": "Learn Firman, Sumec, Elepaq, Tiger, and Honda generators — these are 90% of the Nigerian market. Know their common faults, parts numbers, and where to source spare parts at trade price.", "tools": ["Alaba Market (parts sourcing)", "Generator brand manuals (download free)", "YouTube fault diagnosis videos"]}, {"icon": "🏷️", "name": "Build a transparent price list", "desc": "Servicing: ₦3k–₦8k. Carburettor clean/replace: ₦5k–₦15k. AVR replacement: ₦8k–₦20k. Full overhaul: ₦20k–₦60k. Include parts cost separately. Transparent pricing builds trust and reduces haggling.", "tools": ["WhatsApp Business (price list)", "Canva"]}]}, {"num": 3, "title": "Market Your Services", "time": "Week 3–4", "steps": [{"icon": "📲", "name": "Post in estate WhatsApp groups", "desc": "\'Generator repair and servicing — I come to your location. ₦5,000 servicing + free diagnostic. DM to book.\' Post in 10 estate groups. Generator owners are always looking for a reliable mechanic they can trust to come to them.", "tools": ["WhatsApp", "Facebook Community Groups", "Naijalogic listing"]}, {"icon": "🏠", "name": "Register on Google Business Profile", "desc": "Set up a free Google Business Profile: \'Generator Repair [Your City].\' When someone Googles \'generator repair near me\' — you appear. This is the highest-intent traffic: people actively looking for what you offer.", "tools": ["Google Business Profile (free)", "Google Maps", "Your phone number"]}]}, {"num": 4, "title": "Build Recurring Revenue", "time": "Month 2+", "steps": [{"icon": "📋", "name": "Offer quarterly service contracts", "desc": "Pitch: \'Annual generator maintenance contract — I service your generator every quarter (4× yearly) for ₦15k paid upfront.\' One client on contract = ₦15k guaranteed. 20 contracts = ₦300k/year before any call-out fees.", "tools": ["WhatsApp (contract confirmation)", "Paystack (upfront payment)", "Google Calendar (scheduling)"]}, {"icon": "🛒", "name": "Upsell genuine spare parts", "desc": "Source AVRs, carburettors, and spark plugs from Alaba market at trade price. When replacing a part, charge retail price for the part + labour separately. Parts margin adds 30–50% to your earnings per job.", "tools": ["Alaba Market", "WhatsApp (parts orders)", "Receipts for clients"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('palm-oil-trading', 'Palm Oil Trading & Distribution', '🛢️', 'Buy palm oil at farm gate and sell to Lagos/Abuja markets at 30–50% markup — Nigeria\'s most consumed cooking oil.', '3–4 weeks to first profitable trip', '[{"num": 1, "title": "Learn the Market", "time": "Week 1–2", "steps": [{"icon": "📚", "name": "Understand palm oil grades", "desc": "Grade 1 (bright red, clean): restaurants and households. Grade 2 (darker, slight sediment): industrial use at lower prices. Buying the wrong grade for your market = unsellable stock. Visit Mile 12 Market to learn by sight and smell.", "tools": ["Mile 12 Market visit", "WhatsApp palm oil trading groups", "Experienced traders (informal mentorship)"]}, {"icon": "🗺️", "name": "Research supply states", "desc": "Ondo, Edo, Cross River, and Rivers State are primary producers. Farm-gate price (₦1,200–₦1,800/litre) vs Lagos market price (₦2,500–₦3,500/litre) = your profit margin. Understand transport cost per litre for each state.", "tools": ["WhatsApp groups (state traders)", "Phone calls to farmers", "Google Maps (route planning)"]}]}, {"num": 2, "title": "Source Your First Batch", "time": "Week 2–3", "steps": [{"icon": "🤝", "name": "Find reliable producer contacts", "desc": "The most valuable asset in palm oil trading is a direct producer contact who gives you consistent grade and quantity. Find through: state agricultural associations, WhatsApp commodity groups, or physical visits to producing areas.", "tools": ["NAIOP (Nigeria Association of Palm Oil Producers)", "WhatsApp groups", "Physical state visits"]}, {"icon": "🛢️", "name": "Buy in standard units", "desc": "25-litre kegs are the standard retail unit. Buy 40–100 kegs for a test batch. Negotiate storage at the source — most producers will hold your stock for 1–2 weeks before you arrange haulage.", "tools": ["Phone negotiation", "25-litre kegs (source from market)", "Haulage contacts (WhatsApp)"]}]}, {"num": 3, "title": "Sell Your Stock", "time": "Week 3–4", "steps": [{"icon": "🛒", "name": "Sell to Mile 12 and wholesale markets", "desc": "Mile 12 Market (Lagos) is the pricing benchmark. If you can sell at ₦50–₦200/litre above your all-in cost (purchase + transport + handling), you have a profitable route. Test 2 markets to find your best buyer.", "tools": ["Mile 12 Market (Lagos)", "Bodija Market (Ibadan)", "Onitsha Main Market (Anambra)"]}, {"icon": "📦", "name": "Target supermarkets and restaurants", "desc": "Supermarkets pay ₦100–₦200/litre above wholesale for consistent grade and regular delivery. One supermarket chain buying 500 litres/week at ₦200 margin = ₦100k+ weekly gross profit.", "tools": ["Direct supermarket pitching", "WhatsApp", "Delivery vehicle/partnership"]}]}, {"num": 4, "title": "Build a Distribution Business", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Create monthly supply contracts", "desc": "Negotiate monthly supply agreements with 3–5 steady buyers at a fixed price. Price predictability benefits both sides and removes the stress of re-marketing every batch.", "tools": ["Simple supply contract (Google Docs)", "WhatsApp", "Paystack or bank transfer"]}, {"icon": "🏭", "name": "Move upstream: buy direct from mills", "desc": "Palm oil mills sell crude palm oil (CPO) at ₦900–₦1,400/litre — significantly below refined retail. Refining + repackaging adds another margin layer. This requires ₦500k–₦2m investment but builds a proper commodity business.", "tools": ["State agricultural extension offices", "NAIOP", "Bank financing"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('haulage-truck', 'Haulage & Truck Logistics Business', '🚛', 'One truck on a FMCG contract earns ₦300k–₦1.2m/month — build Nigeria\'s backbone infrastructure from 1 truck to a fleet.', '2–3 months to first contract', '[{"num": 1, "title": "Acquire Your Asset", "time": "Month 1", "steps": [{"icon": "🚛", "name": "Buy a reliable truck", "desc": "Volvo FH, Scania, or Mercedes Actros are preferred for long-haul. For distribution: 7-ton Isuzu or Mitsubishi Fuso. Fairly used: ₦3m–₦8m. New: ₦15m–₦30m. Inspect with a qualified mechanic — hidden engine issues cost ₦500k+ to fix.", "tools": ["Ladipo Market (spare parts benchmark)", "Trusted mechanic for inspection", "Bank vehicle financing (Sterling, LAPO)"]}, {"icon": "📋", "name": "Complete all documentation", "desc": "Road worthiness certificate (FRSC), vehicle registration, LASDRI/state transport license, third-party insurance, and goods-in-transit insurance. Without these, LASTMA and FRSC stops cost ₦10k–₦50k per incident.", "tools": ["FRSC office", "State Motor Vehicle Administration", "Insurance broker"]}]}, {"num": 2, "title": "Register and Position", "time": "Month 1", "steps": [{"icon": "🏢", "name": "Register your haulage company", "desc": "Register with CAC (₦15k–₦30k). Open a business account. Get a company letterhead. Corporate clients (Dangote, Nestlé) will not pay individuals — they need a registered entity with proper invoicing.", "tools": ["CAC registration", "Business bank account (GTBank, Zenith)", "Lawyer (company setup)"]}, {"icon": "🔗", "name": "Join logistics associations", "desc": "Nigeria Association of Logistics Truck Owners (NALTO) and state haulage associations provide route allocation, group insurance rates, and access to load boards when your truck is empty. Membership: ₦20k–₦50k/year.", "tools": ["NALTO", "State haulage associations", "WhatsApp transport groups"]}]}, {"num": 3, "title": "Secure Your First Contract", "time": "Month 1–2", "steps": [{"icon": "📄", "name": "Apply for FMCG contracts", "desc": "Dangote, BUA Foods, Nestlé, Coca-Cola, UAC, and PZ Cussons all outsource haulage. Visit their logistics/procurement departments with: company profile, truck photos, route coverage, and rate schedule. Persistence wins this game.", "tools": ["Company procurement departments", "LinkedIn (logistics managers)", "Industry WhatsApp groups"]}, {"icon": "🌾", "name": "Agricultural commodity haulage", "desc": "Grain, yam, rice, and tomato traders need reliable trucks urgently at harvest time. One phone call from a large Kogi or Benue trader can fill your truck weekly during harvest season (Oct–Dec, Mar–May).", "tools": ["Agricultural commodity traders (WhatsApp)", "Commodity markets (Kogi, Benue visits)", "Rate negotiation"]}]}, {"num": 4, "title": "Scale to a Fleet", "time": "Month 3+", "steps": [{"icon": "🔒", "name": "Protect your investment", "desc": "GPS tracker (₦15k–₦30k) in the cab and under the chassis. Dashboard camera. Strict maintenance schedule: oil every 15k km, full service every 50k km. A well-maintained truck at 5 years is worth more than a neglected one at 2 years.", "tools": ["Teltonika GPS tracker", "DashCam", "Mechanic retainer agreement"]}, {"icon": "📈", "name": "Compound into fleet", "desc": "Use net profit from truck 1 to acquire truck 2 via hire purchase or outright. Fleet of 5 trucks earning ₦400k each = ₦2m/month gross. Hire professional drivers with guarantors and GPS — your role becomes operations management.", "tools": ["Bank vehicle financing", "Fleet GPS management software", "Driver vetting process"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('amazon-kdp-publishing', 'Amazon KDP Self-Publishing', '📖', 'Publish books on Amazon and earn passive dollar royalties — Nigerian authors earning $500–$5,000/month from their laptops.', '4–6 weeks to first published book', '[{"num": 1, "title": "Choose Your Book Strategy", "time": "Week 1", "steps": [{"icon": "🔍", "name": "Find profitable niches with low competition", "desc": "Use Publisher Rocket or free methods: search Amazon for your topic, look at bestsellers ranked 1,000–30,000 (selling 3–30 copies/day), check review counts (under 100 = beatable). Best KDP niches: low-content books (journals, planners), children\'s books, and how-to guides.", "tools": ["Amazon.com (free research)", "Publisher Rocket ($97, one-time)", "KDSpy Chrome extension"]}, {"icon": "📝", "name": "Decide: write it or outsource?", "desc": "For non-fiction and low-content books: write yourself (2–4 weeks). For fiction or content you can\'t produce: hire a ghostwriter on Fiverr ($50–$500). Most successful KDP earners publish 5–20 books, not just 1.", "tools": ["Google Docs (writing)", "Fiverr (ghostwriters)", "Grammarly"]}]}, {"num": 2, "title": "Create Your Book", "time": "Week 1–3", "steps": [{"icon": "📖", "name": "Write or compile your content", "desc": "Non-fiction structure: problem → solution chapters → actionable steps → resources. Aim for 10,000–30,000 words for most non-fiction. Low-content books (planners, journals): design only, no writing needed.", "tools": ["Google Docs", "Scrivener ($49)", "Canva (low-content design)"]}, {"icon": "🎨", "name": "Design a professional cover", "desc": "On Amazon, the cover sells the book. A professional cover costs $5–$30 on Fiverr. Or use Canva\'s KDP cover templates. Study bestselling covers in your genre — pattern match, don\'t reinvent.", "tools": ["Fiverr (cover designers: search \'KDP cover\')", "Canva (DIY)", "Book Bolt (low-content design)"]}]}, {"num": 3, "title": "Publish and Optimize", "time": "Week 3–4", "steps": [{"icon": "🛒", "name": "Set up your KDP account", "desc": "Register at kdp.amazon.com with your Nigerian or US bank account (Payoneer works). Set up your author profile, tax information (form W-8BEN for Nigerians), and direct deposit to Payoneer.", "tools": ["KDP.amazon.com", "Payoneer (free USD account)", "W-8BEN form"]}, {"icon": "🔑", "name": "Optimize your listing for search", "desc": "Amazon is a search engine. Your title, subtitle, and 7 keywords determine discoverability. Use Publisher Rocket or free Amazon autocomplete to find keywords buyers actually type. A good keyword set drives organic sales forever.", "tools": ["Publisher Rocket", "Amazon autocomplete (free)", "KDP backend keywords"]}]}, {"num": 4, "title": "Build a Publishing Business", "time": "Month 2+", "steps": [{"icon": "📚", "name": "Publish your 2nd and 3rd book fast", "desc": "Income compounds with each new book. Book 1: $50/month. Books 1–5: $300/month. Books 1–10: $1,000/month. The first book teaches you the system; the 5th book generates real income.", "tools": ["Google Docs", "Fiverr (ghostwriting)", "Publisher Rocket"]}, {"icon": "🌐", "name": "Enroll in KDP Select for royalty boost", "desc": "KDP Select gives Amazon exclusivity for 90 days in exchange for: 70% royalty globally (vs 35%), Kindle Unlimited page-reads income, and free promotional days. Most Nigerian KDP earners use Select for their first 12 months.", "tools": ["KDP Select enrollment", "Amazon Marketing Services (ads)", "BookBub (promotion)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('bookkeeping-service', 'Bookkeeping & Accounting Service', '📒', 'Provide monthly bookkeeping to Nigerian SMEs who need organised finances but can\'t afford a full-time accountant.', '2–3 weeks to first client', '[{"num": 1, "title": "Build the Skill", "time": "Week 1–2", "steps": [{"icon": "📚", "name": "Master QuickBooks or Wave", "desc": "QuickBooks is the Nigerian SME standard. Wave Accounting is free (perfect for startup clients). Complete a QuickBooks certification course on Coursera or the free QuickBooks training centre. This takes 1–2 weeks.", "tools": ["QuickBooks (30-day free trial)", "Wave Accounting (free)", "Coursera: QuickBooks certification", "QuickBooks Training Centre"]}, {"icon": "📊", "name": "Understand Nigerian tax basics", "desc": "Learn: VAT (7.5%), WHT rates, PAYE calculation, and LIRS/FIRS registration requirements. Clients pay premium for bookkeepers who also understand their tax obligations — not just transaction entry.", "tools": ["FIRS.gov.ng (free guides)", "ICAN Student resources", "YouTube: Nigerian tax tutorials"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 1–2", "steps": [{"icon": "🤝", "name": "Offer free bookkeeping to 2 businesses", "desc": "Approach 2 small businesses — a restaurant and a retail shop — and offer 1 month free bookkeeping. Document what you built: chart of accounts, monthly P&L, bank reconciliation. This is your case study.", "tools": ["Wave Accounting (free for small clients)", "QuickBooks", "Google Sheets"]}, {"icon": "📄", "name": "Create a service agreement template", "desc": "A simple 1-page bookkeeping engagement letter: services included, monthly fee, data delivery method, confidentiality clause. Clients trust structured professionals. ₦1k investment in a lawyer-reviewed template is worth it.", "tools": ["Google Docs (template)", "Paystack (recurring billing)", "DocuSign (free tier)"]}]}, {"num": 3, "title": "Land Paying Clients", "time": "Week 2–3", "steps": [{"icon": "📲", "name": "Target the business WhatsApp economy", "desc": "Post in business owner groups: \'Is your business profitable? Most SMEs lose 15–30% profit because they have no bookkeeping system. I set up and manage your accounts for ₦15k/month.\' This pain-point pitch converts.", "tools": ["WhatsApp Business Groups", "LinkedIn", "Facebook Groups"]}, {"icon": "🏢", "name": "Partner with accountants and tax consultants", "desc": "Chartered Accountants often have SME clients who need monthly bookkeeping but don\'t want to do it themselves. A referral relationship with 3 accountants can fill your entire client book within a month.", "tools": ["ICAN directory", "LinkedIn (accounting professionals)", "WhatsApp"]}]}, {"num": 4, "title": "Scale Your Practice", "time": "Month 2+", "steps": [{"icon": "📈", "name": "Raise prices and niche down", "desc": "After 5 clients, specialize: restaurants and food businesses, e-commerce sellers, or professional services firms. Specialists charge ₦30k–₦80k/month vs generalists at ₦10k–₦20k. Same work, 3× the income.", "tools": ["LinkedIn (niche content)", "Industry WhatsApp groups"]}, {"icon": "👥", "name": "Hire junior bookkeepers", "desc": "At 8+ clients, a ₦30k–₦50k junior bookkeeper handles data entry. You review, advise, and manage client relationships. Scale to 20 clients with a 2-person team — earn ₦400k–₦1m/month with management overhead only.", "tools": ["Upwork (hiring)", "Slack", "QuickBooks accountant access"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('okrika-online', 'Okrika (UK Used Clothing) Online Store', '👗', 'Source quality second-hand fashion from Katangua and sell online at 3–5× margin — daily sales, zero factory cost.', '1–2 weeks to first sales', '[{"num": 1, "title": "Source Smart", "time": "Week 1", "steps": [{"icon": "🛍️", "name": "Master bale buying", "desc": "Katangua Market (Lagos), Ariaria Market (Aba), and Onitsha Main Market sell bales (large pressed bundles of mixed clothing). Grade A bale: ₦30k–₦80k containing 50–100+ pieces. Your profit depends entirely on buying quality bales consistently.", "tools": ["Katangua Market (Lagos)", "Ariaria Market (Aba)", "Experienced trader escort (for first trips)"]}, {"icon": "📊", "name": "Sort and grade your haul", "desc": "After buying: immediately sort into Grade A (excellent condition, brand names, unique pieces — sell ₦3k–₦15k each), Grade B (good but generic — ₦500–₦2k), and Grade C (bundle and sell cheap in bulk). Photo Grade A pieces first.", "tools": ["Clean sorting space", "Steamer/iron (₦3k–₦8k)", "Mannequin or hanger setup"]}]}, {"num": 2, "title": "Build Your Sales Channels", "time": "Week 1", "steps": [{"icon": "📱", "name": "TikTok and Instagram Reels are your engine", "desc": "Film your bale unboxing (huge engagement), clothing styling videos, and before/after posts. Okrika content performs exceptionally well — it\'s aspirational AND affordable. Post 3–5 videos daily when you have new stock.", "tools": ["TikTok", "Instagram Reels", "CapCut (editing)"]}, {"icon": "📲", "name": "Build a WhatsApp order community", "desc": "Create a WhatsApp broadcast list or community group. Post new arrivals at 7am and 7pm daily. \'Today\'s drops — DM to reserve.\' Broadcast members who\'ve bought before are 5× more likely to buy again.", "tools": ["WhatsApp Business", "WhatsApp Broadcast", "Paystack"]}]}, {"num": 3, "title": "Sell Out Every Batch", "time": "Ongoing", "steps": [{"icon": "📸", "name": "Product photography that sells", "desc": "Clean white or neutral background. Natural window light or a ₦3k ring light. Photograph flat-lay and on-body (mannequin or yourself). Each piece deserves 3–4 photos: front, back, close-up detail, label.", "tools": ["Phone camera", "Ring light (₦3k–₦8k)", "Mannequin (₦5k–₦15k)"]}, {"icon": "🚚", "name": "Nationwide delivery system", "desc": "GIG Logistics, Kwik Delivery, and DHL Nigeria handle nationwide delivery. Collect payment via Paystack before shipping. Charge shipping to buyer — ₦1,500–₦3,500 within Nigeria. Never ship without payment.", "tools": ["GIG Logistics", "Kwik Delivery", "Paystack"]}]}, {"num": 4, "title": "Scale the Business", "time": "Month 2+", "steps": [{"icon": "🏷️", "name": "Build a fashion brand", "desc": "Name your business, create a simple logo, and build a consistent Instagram identity. A branded okrika store commands 20–40% premium over \'random seller\' accounts. Brand loyalty means customers wait for YOUR drops.", "tools": ["Canva (logo + branding)", "Instagram", "Paystack Business"]}, {"icon": "🌍", "name": "Sell to diaspora buyers", "desc": "Nigerians in the UK and US buy Nigerian okrika for nostalgia and unique fashion. List on Etsy or Depop with international shipping (DHL Express). A piece bought for ₦500 can sell for $30–$60 to diaspora.", "tools": ["Etsy (international listings)", "Depop", "DHL Express (international shipping)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('aba-goods-middleman', 'Aba Manufactured Goods Middleman', '🧵', 'Connect Aba\'s factories to your city — buy shoes, bags, and clothing at factory price, sell at 40–60% markup.', '4–6 weeks to first profitable supply run', '[{"num": 1, "title": "Know Aba Like a Local", "time": "Week 1–2", "steps": [{"icon": "🗺️", "name": "Study Ariaria International Market", "desc": "Ariaria is divided into sections: shoe section, bag section, clothing section, school uniforms, and leather goods. Visit each section and map factory prices vs retailer prices in your city. This spread is your business opportunity.", "tools": ["First trip to Aba (accommodation ₦5k–₦15k/night)", "WhatsApp trading groups", "Google Maps (Ariaria sections)"]}, {"icon": "🤝", "name": "Build direct factory contacts", "desc": "The key is manufacturers, not retailers. Look for \'factory\' signs, observe who sells at the lowest prices, and ask to visit the production floor. Real manufacturers want large consistent buyers — position yourself as one from day 1.", "tools": ["In-person factory visits", "WhatsApp (manufacturer contacts)", "Business cards"]}]}, {"num": 2, "title": "Your First Order", "time": "Week 2–3", "steps": [{"icon": "📦", "name": "Test with small quantities", "desc": "First order: 50–100 units of 2–3 product types. Shoes at ₦800–₦2,000 factory price that retail for ₦4,000–₦8,000 in Lagos. Confirm quality, sizing accuracy, and manufacturer reliability before placing large orders.", "tools": ["Cash for purchase", "Bags/boxes for transport", "Bolt Cargo or Uber (Aba transport)"]}, {"icon": "🚚", "name": "Transport cost is your margin killer", "desc": "Road transport from Aba to Lagos: ₦2,000–₦5,000/carton depending on size and carrier. Know your transport cost per unit before pricing. A ₦1,200 shoe + ₦400 transport = ₦1,600 landed cost — budget accordingly.", "tools": ["GIG Logistics", "ABC Transport", "Agofure Transport"]}]}, {"num": 3, "title": "Sell in Your City", "time": "Week 3–4", "steps": [{"icon": "🏪", "name": "Sell wholesale to boutiques and retailers", "desc": "Approach boutiques, market traders, Instagram fashion stores, and school uniform suppliers in your city. Offer them 15–20% below what they currently pay from their supplier. You become their preferred supplier.", "tools": ["WhatsApp", "Direct store visits", "Instagram (find stores in your city)"]}, {"icon": "📱", "name": "Build a retail WhatsApp catalogue", "desc": "Photograph all products cleanly and create a WhatsApp catalogue. Post new arrivals on status daily. WhatsApp retail alongside wholesale gives you 2 income streams from the same stock at different price points.", "tools": ["WhatsApp Business Catalogue", "Phone camera", "Instagram"]}]}, {"num": 4, "title": "Build a Supply Chain Business", "time": "Month 2+", "steps": [{"icon": "🔄", "name": "Set monthly supply cycles", "desc": "Aba trip every 3–4 weeks. Same manufacturers, same products, same buyers. Predictability on both ends lets you negotiate better factory prices (for volume) and better sale prices (for reliability). This is the business model.", "tools": ["Google Sheets (inventory tracking)", "WhatsApp (manufacturer + buyer coordination)"]}, {"icon": "🏷️", "name": "Private label your products", "desc": "Ask Aba manufacturers to produce with your brand label (minimum orders typically 200–500 units). Branded products sell at 30–50% premium. Your name on the product prevents price comparison with competitors.", "tools": ["Canva (label design)", "Aba manufacturer (custom labeling)", "Instagram (brand building)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('event-photography', 'Event Photography', '📸', 'Capture Nigeria\'s biggest celebrations — birthdays, weddings, and corporate events at ₦50k–₦500k per booking.', '3–4 weeks to first paid booking', '[{"num": 1, "title": "Master Your Camera", "time": "Week 1–2", "steps": [{"icon": "📷", "name": "Learn the basics properly", "desc": "Understanding exposure triangle (aperture, shutter speed, ISO) is non-negotiable. Shoot RAW format, not JPEG. Learn your specific camera\'s autofocus system for low-light event environments. YouTube: Peter McKinnon, Tony Northrup.", "tools": ["YouTube: Peter McKinnon", "YouTube: Tony Northrup", "Your DSLR/Mirrorless camera"]}, {"icon": "🌟", "name": "Master flash photography", "desc": "Nigerian events are typically indoors with poor lighting. A Godox TT685 speedlight (₦25k–₦40k) is the single most impactful purchase after the camera. Learn: bounce flash, off-camera flash, and fill flash in bright outdoor sun.", "tools": ["Godox TT685 Speedlight", "YouTube: Photography Talk channel", "Lightroom (editing)"]}]}, {"num": 2, "title": "Build a Portfolio", "time": "Week 1–3", "steps": [{"icon": "📸", "name": "Shoot events for free first", "desc": "Offer to cover a friend\'s birthday, a church event, and a small corporate function for free. Deliver 100–200 professionally edited photos within 72 hours. These become your portfolio and your first testimonials.", "tools": ["Adobe Lightroom (free trial)", "Google Drive (delivery)", "Instagram (portfolio)"]}, {"icon": "🎨", "name": "Develop an editing style", "desc": "Your editing preset = your brand. Nigerian clients prefer: bright skin tones, vibrant colours, and clean backgrounds. Create 3–5 Lightroom presets and apply them consistently. Clients should recognize your work instantly.", "tools": ["Adobe Lightroom", "VSCO presets", "YouTube: Lightroom tutorials"]}]}, {"num": 3, "title": "Get Bookings", "time": "Week 3–4", "steps": [{"icon": "📲", "name": "Instagram is your booking engine", "desc": "Post 3 photos from every event. Use: #LagosBirthday #LagosWeddingPhotographer #AbujaCorporateEvents. Reply to every DM within 1 hour — event photography bookings are time-sensitive decisions.", "tools": ["Instagram", "TikTok (BTS content)", "WhatsApp Business"]}, {"icon": "🤝", "name": "Partner with event planners", "desc": "One event planner who trusts your work sends you 3–5 bookings per month. Find them on Instagram, attend their events, and offer a referral commission of ₦5k–₦15k per booking they send you.", "tools": ["Instagram (event planner outreach)", "WhatsApp", "Business cards"]}]}, {"num": 4, "title": "Scale Your Photography Business", "time": "Month 2+", "steps": [{"icon": "💰", "name": "Corporate events pay the most", "desc": "Corporate events: product launches, staff parties, award ceremonies pay ₦150k–₦500k for the same 4 hours of work as a birthday party that pays ₦50k–₦100k. Target corporate Lagos/Abuja aggressively.", "tools": ["LinkedIn (corporate event managers)", "PR agencies", "Corporate WhatsApp groups"]}, {"icon": "👥", "name": "Build a photography team", "desc": "At 3+ bookings per weekend, you need a second shooter and a video person. Package photography + videography: ₦200k–₦600k per event. Hire freelance videographers per event and take 30–40% coordination margin.", "tools": ["WhatsApp (team coordination)", "Google Calendar (booking system)", "Paystack"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('makeup-artist', 'Professional Makeup Artist', '💄', 'Build a bridal and events makeup business — ₦5k–₦50k per face and weekend bookings that fill months in advance.', '2–4 weeks to first paying clients', '[{"num": 1, "title": "Master Your Craft", "time": "Week 1–3", "steps": [{"icon": "💄", "name": "Get trained by a professional", "desc": "Attend a structured makeup artistry course (₦50k–₦200k for reputable Lagos/Abuja schools). YouTube can supplement but not replace hands-on training in product selection, blending, and application techniques for Nigerian skin tones.", "tools": ["Makeup school (Instagram: search \'makeup school Lagos\')", "YouTube: Jackie Aina (Black skin expertise)", "YouTube: Robert Welsh"]}, {"icon": "💋", "name": "Build your kit carefully", "desc": "Start with quality over quantity: 2 foundation brushes, 1 blending sponge, key eye brushes, a good setting spray, and 5–6 versatile eyeshadow palettes. Total starter kit: ₦30k–₦80k. Bad products on dark skin = bad portfolio.", "tools": ["Beautyco (Lagos)", "Makeup supplies in Dosunmu Market", "Beauty Bay (online)"]}]}, {"num": 2, "title": "Build Your Portfolio", "time": "Week 2–4", "steps": [{"icon": "📸", "name": "Create your signature looks", "desc": "Develop 5 looks you can execute perfectly: natural glam, full glam, bridal, editorial, and party makeup. Practice on friends and photograph in good light. Your Instagram is your portfolio — quality over quantity.", "tools": ["Natural window light (free)", "Phone camera", "Adobe Lightroom (skin tone editing)"]}, {"icon": "🎬", "name": "Create transformation content", "desc": "Before/after Reels are the highest-converting makeup content. Film the before, then cut to the final look with trending audio. These videos get shared, saved, and bring bookings without any paid advertising.", "tools": ["TikTok", "Instagram Reels", "CapCut (video editing)"]}]}, {"num": 3, "title": "Fill Your Calendar", "time": "Month 1", "steps": [{"icon": "💍", "name": "Target brides first", "desc": "Bridal makeup (₦15k–₦80k per face) is your highest-value booking and generates the most referrals. One happy bride refers you to her entire bridal train. Market in: wedding hashtags, wedding Facebook groups, and bridal expos.", "tools": ["Instagram: #LagosBride #AbujaBride", "Facebook Wedding Groups", "Wedding expos (₦10k–₦30k booth)"]}, {"icon": "🎉", "name": "Expand to events and aso-ebi groups", "desc": "Birthday parties, graduations, and aso-ebi groups (5–20 faces/event) at ₦5k–₦15k per face are your consistent weekly income. One aso-ebi group per weekend = ₦25k–₦150k.", "tools": ["WhatsApp (group bookings)", "Instagram", "Event planners referral network"]}]}, {"num": 4, "title": "Build a Makeup Business", "time": "Month 3+", "steps": [{"icon": "🎓", "name": "Start teaching makeup classes", "desc": "A 1–2 day makeup course at ₦20k–₦80k per student earns more per hour than doing makeup. Teach 5 students/class = ₦100k–₦400k per class day. Students also become your referral network for bookings.", "tools": ["Instagram (class promotion)", "Paystack", "WhatsApp"]}, {"icon": "💄", "name": "Launch a product line", "desc": "Custom lip gloss or eyeshadow palettes branded with your name (minimum order 50–100 units from Chinese manufacturers via Alibaba — $200–$500). Your existing makeup community buys from you. This creates passive income alongside services.", "tools": ["Alibaba (private label cosmetics)", "Paystack", "Instagram Shop"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('tax-filing-service', 'Tax Filing & Compliance Service', '📋', 'Help Nigerian businesses and individuals file taxes correctly — earn ₦20k–₦150k per client per filing season.', '2–3 weeks to first client', '[{"num": 1, "title": "Build Technical Knowledge", "time": "Week 1–2", "steps": [{"icon": "📚", "name": "Master Nigerian tax law basics", "desc": "Study: Personal Income Tax Act (PITA), Company Income Tax Act (CITA), VAT Act (7.5%), and WHT rates. Download FIRS guidelines free. ICAN student resources are the best structured learning path for Nigerian tax.", "tools": ["FIRS.gov.ng (official guidelines)", "ICAN study materials", "YouTube: Nigerian tax professionals"]}, {"icon": "💻", "name": "Learn tax filing platforms", "desc": "FIRS TaxPro Max is the new federal tax filing system. Lagos State uses LIRS e-Tax portal. Master both. The ability to navigate government portals quickly is a significant value-add clients pay for.", "tools": ["TaxProMax (FIRS)", "LIRS e-Tax Portal", "State IRS portals"]}]}, {"num": 2, "title": "Get Certified", "time": "Week 2–3", "steps": [{"icon": "🎓", "name": "Enroll in CITN or ICAN", "desc": "Chartered Institute of Taxation of Nigeria (CITN) Student membership gives you legal standing to represent clients. ICAN also covers taxation. Entry level: ₦15k–₦30k registration fee. This credential is what justifies premium fees.", "tools": ["CITN.org", "ICAN Student Portal"]}, {"icon": "📄", "name": "Create your service packages", "desc": "Individual annual tax return: ₦10k–₦20k. SME annual tax filing (CIT + VAT + WHT): ₦50k–₦150k. Monthly VAT returns: ₦10k–₦20k/month retainer. Bundle services for best client value perception.", "tools": ["Canva (services brochure)", "Paystack", "Google Docs"]}]}, {"num": 3, "title": "Build Your Client Base", "time": "Week 2–4", "steps": [{"icon": "📲", "name": "Target SME owners on LinkedIn and WhatsApp", "desc": "Post educational content: \'Did you know your company owes WHT on every professional service payment above ₦10k?\' Education that reveals a problem positions you as the solution expert before you pitch anything.", "tools": ["LinkedIn", "WhatsApp", "Facebook Business Groups"]}, {"icon": "🤝", "name": "Partner with accountants and lawyers", "desc": "Lawyers and accountants have clients who need tax filing but it\'s not their core service. A referral agreement (10–20% of fees) with 5 professionals fills your client book within weeks.", "tools": ["ICAN directory", "LinkedIn (accounting professionals)", "WhatsApp"]}]}, {"num": 4, "title": "Build a Tax Practice", "time": "Month 2+", "steps": [{"icon": "📊", "name": "January–March is your peak season", "desc": "Individual PITA returns are due March 31st, CIT returns June 30th. Build a waiting list through October–December for the filing season rush. Peak season at 20 clients = ₦1m+ in 90 days.", "tools": ["Google Calendar (deadline tracking)", "Paystack", "Client database (Google Sheets)"]}, {"icon": "🏢", "name": "Add LIRS and FIRS controversy resolution", "desc": "When FIRS or LIRS sends assessment notices, businesses panic. Tax controversy resolution charges ₦100k–₦500k+ per case. Build expertise in this area — it\'s the highest-value tax service and has zero seasonality.", "tools": ["FIRS dispute resolution portal", "CITN representation guidelines", "Lawyer partnership"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('caricature-portrait-art', 'Caricature & Digital Portrait Art', '🎭', 'Draw digital portraits and caricatures for events, social media, and gifts — earn ₦10k–₦100k per commission.', '2–3 weeks to first commission', '[{"num": 1, "title": "Develop Your Style", "time": "Week 1–2", "steps": [{"icon": "✏️", "name": "Practice caricature fundamentals", "desc": "Caricature amplifies key features: exaggerate jawlines, noses, eyes. Draw 50 caricatures of celebrities and public figures from reference photos. Consistency and recognizability are more important than photorealism.", "tools": ["Procreate (iPad, ₦5k–₦10k)", "Clip Studio Paint (PC, free trial)", "YouTube: Aaron Blaise (character drawing)"]}, {"icon": "🎨", "name": "Build a diverse portfolio", "desc": "Create samples across styles: classic caricature, realistic portrait, cartoon style, and chibi. Different clients want different styles — versatility = more commissions.", "tools": ["Procreate", "Adobe Illustrator", "ArtStation (free portfolio)"]}]}, {"num": 2, "title": "Launch on Instagram and Fiverr", "time": "Week 2", "steps": [{"icon": "📲", "name": "Instagram is your showcase", "desc": "Post a new piece daily. Film your drawing process as a Reel (high shares). Use hashtags: #NigerianArtist #DigitalPortrait #Caricature #ProcreateArt. Your first 100 followers are your first potential clients.", "tools": ["Instagram", "TikTok (speed drawing)", "CapCut (screen recording edit)"]}, {"icon": "🛍️", "name": "List on Fiverr and international platforms", "desc": "Create a Fiverr gig: \'Digital portrait/caricature from your photo.\' Buyers from USA, UK, UAE pay $20–$150 per portrait. Price in USD. Nigerian art has a premium on international markets.", "tools": ["Fiverr", "ArtStation (portfolio)", "Payoneer (USD payment)"]}]}, {"num": 3, "title": "Build Nigerian Event Revenue", "time": "Month 1", "steps": [{"icon": "🎉", "name": "Events are your Nigerian goldmine", "desc": "Corporate events, birthday parties, and weddings hire live caricature artists at ₦50k–₦150k per event (2–4 hours). One event planner relationship = 3–5 bookings per month.", "tools": ["Instagram (event planners)", "WhatsApp", "Event planning groups"]}, {"icon": "🎁", "name": "Push gift commissions aggressively", "desc": "\'Surprise your parent/partner with a custom portrait!\' Peak seasons: Mother\'s Day, Father\'s Day, Valentine\'s, and Christmas. Run paid Instagram ads (₦2k/day for 5 days) targeting Lagos and Abuja gift buyers 2 weeks before these dates.", "tools": ["Instagram Ads", "Canva (ad creative)", "Paystack"]}]}, {"num": 4, "title": "Build Passive Income", "time": "Month 2+", "steps": [{"icon": "🖼️", "name": "Sell digital products", "desc": "Sell Procreate brushes, illustration packs, and drawing tutorials on Gumroad or Selar. Your audience trusts your skill — they\'ll buy tools that help them improve. One brush pack sold 500 times = passive income.", "tools": ["Gumroad", "Selar.co", "Instagram (promotion)"]}, {"icon": "📚", "name": "Teach online courses", "desc": "A \'Learn Procreate in 30 Days\' course at ₦8k–₦20k, sold to your Instagram audience of aspiring artists, can earn ₦200k+ in a single launch. You teach once — the course sells forever.", "tools": ["Selar.co", "Zoom (live classes)", "Canva (course materials)"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('educational-content-creator', 'Educational Content Creator', '📚', 'Create educational content on YouTube or TikTok and build an audience that pays you — via AdSense, brands, and courses.', '3–6 months to first monetization', '[{"num": 1, "title": "Choose Your Niche", "time": "Week 1", "steps": [{"icon": "🎯", "name": "Find a profitable education niche", "desc": "Best performing Nigerian education niches: JAMB/WAEC exam prep, finance and investment in Nigeria, digital skills (Excel, coding), business and entrepreneurship, and legal/rights education. Pick the intersection of your knowledge and market demand.", "tools": ["Google Trends Nigeria", "YouTube (search your topic + Nigeria)", "TikTok (search education content)"]}, {"icon": "🏆", "name": "Study successful channels", "desc": "Find the top 3 creators in your niche. Analyse: what topics perform best, video length, thumbnail style, and comment section (what questions do viewers ask? These are your content ideas).", "tools": ["YouTube (competitor analysis)", "TubeBuddy (free tier)", "Social Blade (channel analytics)"]}]}, {"num": 2, "title": "Start Creating", "time": "Week 1–4", "steps": [{"icon": "🎥", "name": "Phone + window light is enough", "desc": "A tripod (₦3k–₦8k) and a window facing you is all you need for your first 30 videos. Content quality (accuracy, clarity, value) matters infinitely more than production quality for educational content.", "tools": ["Phone camera", "Tripod (₦3k–₦8k)", "CapCut or DaVinci Resolve (editing)"]}, {"icon": "📅", "name": "Post 3–5 videos per week consistently", "desc": "The algorithm rewards consistency over perfection. Commit to a posting schedule and keep it for 90 days minimum before evaluating results. Most creators quit before the algorithm favours them — your persistence is your competitive advantage.", "tools": ["YouTube Studio", "TikTok", "Google Calendar (content calendar)"]}]}, {"num": 3, "title": "Grow Your Audience", "time": "Month 1–3", "steps": [{"icon": "❓", "name": "Answer real questions from real students", "desc": "Read comments and direct messages daily. Every question asked is a video idea. Videos that answer specific questions rank on both YouTube and Google search — free traffic forever.", "tools": ["YouTube Comments", "TikTok DMs", "AnswerThePublic.com (question research)"]}, {"icon": "📲", "name": "Cross-promote on all platforms", "desc": "Post YouTube videos as TikToks and Reels (shorter clips). Post Twitter threads summarizing each video. Build a WhatsApp broadcast list. The audience that follows you in 3 places is 5× more loyal than the one that follows you in 1.", "tools": ["TikTok", "Instagram", "Twitter/X", "WhatsApp Broadcast"]}]}, {"num": 4, "title": "Monetize Multiple Streams", "time": "Month 3+", "steps": [{"icon": "💰", "name": "YouTube Partner Program at 1,000 subscribers", "desc": "Apply for monetization at 1,000 subscribers and 4,000 watch hours. Nigerian education channels typically earn $1–$5 per 1,000 views (RPM). 100,000 monthly views = $100–$500 AdSense income.", "tools": ["YouTube Studio", "AdSense"]}, {"icon": "📦", "name": "Digital products are your real income", "desc": "WAEC past question compendiums (₦1k–₦3k), revision guides, spreadsheet templates, or mini-courses. Your audience trusts your expertise — they\'ll pay for packaged knowledge that saves them time.", "tools": ["Selar.co", "Paystack", "Mailchimp"]}]}]');
INSERT IGNORE INTO `roadmaps` (`hustle_id`, `name`, `emoji`, `summary`, `duration`, `phases`) VALUES
('digital-marketing-agency-sme', 'Digital Marketing Agency (SME Clients)', '📣', 'Package multiple digital services and earn ₦200k–₦1m/month serving Nigerian SMEs who need a full marketing team.', '4–6 weeks to first retainer', '[{"num": 1, "title": "Build the Service Stack", "time": "Week 1–2", "steps": [{"icon": "🛠️", "name": "Master the core services", "desc": "An SME digital marketing agency needs: social media management, Google Ads basics, Facebook/Instagram Ads, SEO fundamentals, and email marketing. You don\'t need to be expert-level in all — competence + results + clear communication beats perfection.", "tools": ["Meta Blueprint (free)", "Google Skillshop (free)", "HubSpot Academy (free)", "Semrush Academy (free)"]}, {"icon": "📦", "name": "Build clear service packages", "desc": "Starter Pack (₦80k/month): Social media management (3 platforms) + weekly content. Growth Pack (₦150k/month): + Facebook/Google Ads (₦50k ad spend managed). Full Service (₦250k/month): + SEO + email marketing. Clear packages prevent scope creep.", "tools": ["Canva (agency deck)", "Google Docs (service agreement)", "Paystack"]}]}, {"num": 2, "title": "Build Case Studies", "time": "Week 1–3", "steps": [{"icon": "📊", "name": "Work for free to prove results", "desc": "Approach 2 small businesses and offer 30 days free digital marketing in exchange for permission to document and share results. Before/after metrics — followers, website traffic, enquiries — are your agency\'s most powerful sales tool.", "tools": ["Meta Business Suite", "Google Analytics", "Canva (case study design)"]}, {"icon": "🎯", "name": "Pick one industry to specialize in", "desc": "Agencies that specialize in one industry (e-commerce, hospitality, real estate, healthcare) earn 3× more than generalists. Pick the industry where your network or knowledge gives you an edge.", "tools": ["LinkedIn (industry research)", "Industry WhatsApp groups"]}]}, {"num": 3, "title": "Land Retainer Clients", "time": "Week 3–5", "steps": [{"icon": "📲", "name": "Cold outreach via LinkedIn and WhatsApp", "desc": "Find business owners of growing SMEs on LinkedIn. Send a very specific pitch: \'I reviewed your Instagram — your engagement rate is 0.3% against the industry average of 2.5%. I know exactly how to fix this. 15-minute call?\'", "tools": ["LinkedIn Sales Navigator (free trial)", "Gmail", "WhatsApp"]}, {"icon": "🎤", "name": "Speak at business events", "desc": "Offer to speak for free at business associations, entrepreneur events, and startup meetups on \'5 digital marketing mistakes Nigerian SMEs make.\' A 20-minute talk in front of 50 business owners = 5–10 qualified inbound leads.", "tools": ["Lagos Business School events", "Startup Lagos", "LagosTech community events"]}]}, {"num": 4, "title": "Scale the Agency", "time": "Month 3+", "steps": [{"icon": "👥", "name": "Hire specialists, not generalists", "desc": "At ₦500k+ revenue, hire a Facebook Ads specialist (₦50k/month) and a content creator (₦40k/month). You handle client relationships and strategy — specialists execute. Your margins improve as you offload execution.", "tools": ["LinkedIn (hiring)", "Slack", "ClickUp (project management)"]}, {"icon": "📈", "name": "Add performance-based pricing", "desc": "Instead of flat retainers, offer: base fee + % of revenue generated or % of ad spend managed. Performance pricing aligns your incentive with client success and justifies exponentially higher fees as results improve.", "tools": ["Google Analytics (revenue tracking)", "Meta Ads Manager", "Monthly reporting dashboard"]}]}]');
